def minPath(grid: list[list[int]], k: int) -> list[int]:
    n = len(grid)

    # Locate the cell holding the value 1 (the smallest possible first value).
    pos = {}
    for r in range(n):
        for c in range(n):
            pos[grid[r][c]] = (r, c)

    r, c = pos[1]
    result = [1]

    for _ in range(k - 1):
        best = None
        best_val = None
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                v = grid[nr][nc]
                if best_val is None or v < best_val:
                    best_val = v
                    best = (nr, nc)
        r, c = best
        result.append(best_val)

    return result
```

