def order_by_points(nums: list[int]) -> list[int]:
    def signed_digit_sum(n: int) -> int:
        digits = str(abs(n))
        if n < 0:
            return -int(digits[0]) + sum(int(d) for d in digits[1:])
        return sum(int(d) for d in digits)

    return sorted(nums, key=signed_digit_sum)
```

