def merge_intervals(intervals) -> list[list[int]]:
    result = []
    for start, end in sorted((list(iv) for iv in intervals), key=lambda iv: iv[0]):
        if result and start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)
        else:
            result.append([start, end])
    return result
```

