def normalize_phone(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    allowed_punct = set(" -.()")
    digits = []
    for i, ch in enumerate(s):
        if ch in "0123456789":
            digits.append(ch)
        elif ch in allowed_punct:
            continue
        elif ch == "+" and i == 0:
            continue
        else:
            raise ValueError(f"invalid character {ch!r} in phone number")

    number = "".join(digits)

    if len(number) == 11 and number[0] == "1":
        number = number[1:]

    if len(number) != 10:
        raise ValueError("phone number must contain exactly 10 digits")

    area, exchange, subscriber = number[:3], number[3:6], number[6:]

    if area[0] in "01":
        raise ValueError("area code must not start with 0 or 1")
    if exchange[0] in "01":
        raise ValueError("exchange code must not start with 0 or 1")

    return f"({area}) {exchange}-{subscriber}"
```

