from collections import OrderedDict


class TTLCache:
    """LRU cache whose entries expire after a fixed time-to-live.

    Time is supplied explicitly by the caller as `now`; the cache never
    reads a clock. An entry written at time t expires at t + ttl and is
    considered expired whenever now >= t + ttl.
    """

    def __init__(self, capacity: int, ttl: float):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, expires_at); ordered from least to most recently used
        self._entries = OrderedDict()

    def _is_expired(self, expires_at: float, now: float) -> bool:
        return now >= expires_at

    def _purge_expired(self, now: float) -> None:
        expired_keys = [
            k for k, (_, expires_at) in self._entries.items()
            if self._is_expired(expires_at, now)
        ]
        for k in expired_keys:
            del self._entries[k]

    def put(self, key, value, now: float) -> None:
        expires_at = now + self._ttl

        if key in self._entries:
            # Overwrite: reset expiry, mark most recently used, never evict.
            self._entries[key] = (value, expires_at)
            self._entries.move_to_end(key)
            return

        # Inserting a new key.
        if len(self._entries) >= self._capacity:
            self._purge_expired(now)
            if len(self._entries) >= self._capacity:
                # Still full: evict the least recently used entry.
                self._entries.popitem(last=False)

        self._entries[key] = (value, expires_at)

    def get(self, key, now: float):
        entry = self._entries.get(key)
        if entry is None:
            return None

        value, expires_at = entry
        if self._is_expired(expires_at, now):
            del self._entries[key]
            return None

        # Mark as most recently used; expiry is NOT extended.
        self._entries.move_to_end(key)
        return value

    def size(self, now: float) -> int:
        return sum(
            1 for _, expires_at in self._entries.values()
            if not self._is_expired(expires_at, now)
        )
```

