import csv
import io


def column_stats(csv_text: str, column: str) -> dict:
    reader = csv.reader(io.StringIO(csv_text))

    # Find the header: the first non-blank line.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [cell.strip() for cell in row]
            break

    if header is None or column not in header:
        raise KeyError(column)

    idx = header.index(column)

    values = []
    for row in reader:
        # Skip blank lines.
        if not any(cell.strip() for cell in row):
            continue
        cell = row[idx].strip() if idx < len(row) else ""
        if cell == "":
            continue
        values.append(float(cell))  # raises ValueError if not numeric

    if not values:
        return {"count": 0, "sum": 0.0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": len(values),
        "sum": total,
        "mean": total / len(values),
        "min": min(values),
        "max": max(values),
    }
```

