def color_graph(nodes, edges, k, precolored=None):
    """Return a proper k-coloring of the graph as a dict, or None if none exists.

    nodes:      iterable of hashable node names (endpoints of edges are also nodes)
    edges:      list of (u, v) pairs describing an undirected graph
    k:          number of available colors, labeled 0 .. k-1
    precolored: optional dict mapping some nodes to fixed colors that must be kept
    """
    # Collect every node, preserving first-seen order.
    all_nodes = []
    seen = set()

    def add_node(n):
        if n not in seen:
            seen.add(n)
            all_nodes.append(n)

    for n in nodes:
        add_node(n)

    adj = {}
    edge_list = []
    for e in edges:
        u, v = e
        if u == v:
            return None  # self-loop can never be properly colored
        add_node(u)
        add_node(v)
        edge_list.append((u, v))
    for n in all_nodes:
        adj[n] = set()
    for u, v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    precolored = dict(precolored) if precolored else {}
    for n in precolored:
        add_node(n)
        adj.setdefault(n, set())

    if not all_nodes:
        return {}
    if not isinstance(k, int) or k <= 0:
        return None

    # Validate precolorings: in range, and no conflicts between precolored neighbors.
    for n, c in precolored.items():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None
    for u, v in edge_list:
        if u in precolored and v in precolored and precolored[u] == precolored[v]:
            return None

    coloring = dict(precolored)

    def solve():
        uncolored = [n for n in all_nodes if n not in coloring]
        if not uncolored:
            return True

        # Choose the uncolored node with the fewest available colors (MRV).
        best = None
        best_avail = None
        for n in uncolored:
            used = {coloring[m] for m in adj[n] if m in coloring}
            avail = [c for c in range(k) if c not in used]
            if best is None or len(avail) < len(best_avail):
                best = n
                best_avail = avail
                if not avail:
                    return False  # dead end: this node cannot be colored

        for c in best_avail:
            coloring[best] = c
            if solve():
                return True
            del coloring[best]
        return False

    if solve():
        return {n: coloring[n] for n in all_nodes}
    return None
```

