class Editor:
    def __init__(self) -> None:
        self._text = ""
        self._cursor = 0
        self._undo_stack = []  # entries: (before_state, after_state)
        self._redo_stack = []  # entries: (before_state, after_state)

    @property
    def text(self) -> str:
        return self._text

    @property
    def cursor(self) -> int:
        return self._cursor

    def _state(self):
        return (self._text, self._cursor)

    def _restore(self, state) -> None:
        self._text, self._cursor = state

    def _record(self, before, after) -> None:
        self._undo_stack.append((before, after))
        self._redo_stack.clear()

    def insert(self, s: str) -> None:
        before = self._state()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)
        self._record(before, self._state())

    def delete(self, n: int) -> None:
        k = min(n, self._cursor) if n > 0 else 0
        if k <= 0:
            return
        before = self._state()
        start = self._cursor - k
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start
        self._record(before, self._state())

    def move(self, pos: int) -> None:
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        before, after = self._undo_stack.pop()
        self._restore(before)
        self._redo_stack.append((before, after))
        return True

    def redo(self) -> bool:
        if not self._redo_stack:
            return False
        before, after = self._redo_stack.pop()
        self._restore(after)
        self._undo_stack.append((before, after))
        return True
