from decimal import Decimal


def compare_one(a, b):
    def to_num(x):
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, str):
            return Decimal(x.strip().replace(',', '.'))
        raise TypeError(f"Unsupported type: {type(x).__name__}")

    na, nb = to_num(a), to_num(b)
    if na == nb:
        return None
    return a if na > nb else b
```

