    Scale:
        4.0           -> A+
        (3.7, 4.0)    -> A
        (3.3, 3.7]    -> A-
        (3.0, 3.3]    -> B+
        (2.7, 3.0]    -> B
        (2.3, 2.7]    -> B-
        (2.0, 2.3]    -> C+
        (1.7, 2.0]    -> C
        (1.3, 1.7]    -> C-
        (1.0, 1.3]    -> D+
        (0.7, 1.0]    -> D
        (0.0, 0.7]    -> D-
        0.0           -> E
    """
    letter_grades = []
    for gpa in grades:
        if gpa >= 4.0:
            letter = "A+"
        elif gpa > 3.7:
            letter = "A"
        elif gpa > 3.3:
            letter = "A-"
        elif gpa > 3.0:
            letter = "B+"
        elif gpa > 2.7:
            letter = "B"
        elif gpa > 2.3:
            letter = "B-"
        elif gpa > 2.0:
            letter = "C+"
        elif gpa > 1.7:
            letter = "C"
        elif gpa > 1.3:
            letter = "C-"
        elif gpa > 1.0:
            letter = "D+"
        elif gpa > 0.7:
            letter = "D"
        elif gpa > 0.0:
            letter = "D-"
        else:
            letter = "E"
        letter_grades.append(letter)
    return letter_grades
