def compress(s):
    if not s:
        return ""
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        out.append(ch)
        if count > 1:
            out.append(str(count))
        i = j
    return "".join(out)


def decompress(s):
    out = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        i += 1
        start = i
        while i < n and s[i].isdigit():
            i += 1
        count = int(s[start:i]) if i > start else 1
        out.append(ch * count)
    return "".join(out)
