import re

_ALLOWED_CHARS = re.compile(r"\+?[0-9\s().\-]+")


def normalize_phone(s):
    if not isinstance(s, str):
        raise TypeError("phone number must be a string")

    text = s.strip()
    if not _ALLOWED_CHARS.fullmatch(text):
        raise ValueError(f"invalid phone number: {s!r}")

    if text.count("(") > 1 or text.count(")") > 1 or text.count("(") != text.count(")"):
        raise ValueError(f"invalid phone number: {s!r}")

    has_plus = text.startswith("+")
    digits = "".join(ch for ch in text if "0" <= ch <= "9")

    if has_plus:
        if len(digits) != 11 or digits[0] != "1":
            raise ValueError(f"invalid phone number: {s!r}")
        digits = digits[1:]
    elif len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]

    if len(digits) != 10:
        raise ValueError(f"invalid phone number: {s!r}")

    area, exchange, line = digits[:3], digits[3:6], digits[6:]
    if area[0] in "01" or exchange[0] in "01":
        raise ValueError(f"invalid phone number: {s!r}")

    return f"({area}) {exchange}-{line}"
