)

_ROMAN_TO_INT = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    """Convert an integer in the range 1..3999 to a Roman numeral string.

    Raises ValueError if n is not an int (bools are rejected) or is out of range.
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"expected an integer, got {type(n).__name__}")
    if not 1 <= n <= 3999:
        raise ValueError(f"value must be between 1 and 3999, got {n}")

    parts = []
    remaining = n
    for value, symbol in _ROMAN_VALUES:
        count, remaining = divmod(remaining, value)
