def parse_kv(line):
    def split_fields(s):
        fields, buf, in_q, i = [], [], False, 0
        while i < len(s):
            c = s[i]
            if in_q and c == '\\' and i + 1 < len(s):
                buf.append(c)
                buf.append(s[i + 1])
                i += 2
                continue
            if c == '"':
                in_q = not in_q
            if c == ';' and not in_q:
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(c)
            i += 1
        fields.append(''.join(buf))
        return fields

    def find_unquoted_eq(s):
        in_q, i = False, 0
        while i < len(s):
            c = s[i]
            if in_q and c == '\\' and i + 1 < len(s):
                i += 2
                continue
            if c == '"':
                in_q = not in_q
            elif c == '=' and not in_q:
                return i
            i += 1
        return -1

    def unquote(v):
        if len(v) >= 2 and v[0] == '"' and v[-1] == '"':
            inner = v[1:-1]
            out, i = [], 0
            while i < len(inner):
                if inner[i] == '\\' and i + 1 < len(inner):
                    out.append(inner[i + 1])
                    i += 2
                else:
                    out.append(inner[i])
                    i += 1
            return ''.join(out)
        return v

    result = {}
    for field in split_fields(line):
        field = field.strip()
        if not field:
            continue
        eq = find_unquoted_eq(field)
        if eq == -1:
            result[field] = True
        else:
            key = field[:eq].strip()
            value = field[eq + 1:].strip()
            result[key] = unquote(value)
    return result
