import csv
import io


def column_stats(csv_text, column):
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None or column not in reader.fieldnames:
        raise KeyError(f"Column {column!r} not found in CSV header")

    values = []
    for row in reader:
        cell = row.get(column)
        if cell is None:
            continue
        cell = cell.strip()
        if cell == "":
            continue
        try:
            value = int(cell)
        except ValueError:
            value = float(cell)
        values.append(value)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
```

