from collections import OrderedDict


class TTLCache:
    """An LRU cache whose entries expire `ttl` seconds after they are written.

    The current time is always supplied by the caller as `now`.
    An entry written at time t is valid while now < t + ttl and
    expires once now >= t + ttl.
    """

    def __init__(self, capacity, ttl):
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, expires_at); ordered from least to most recently used
        self._data = OrderedDict()

    def _is_expired(self, expires_at, now):
