        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
