class VendingMachine:
    DENOMINATIONS = (25, 10, 5)

    def __init__(self, prices, coins):
        self.prices = dict(prices)
        self.coins = {d: 0 for d in self.DENOMINATIONS}
        for denomination, count in dict(coins).items():
            if denomination in self.coins:
                self.coins[denomination] = count
        self._inserted = []

    def insert(self, coin):
        if coin not in self.DENOMINATIONS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def _make_change(self, amount):
        n25 = self.coins[25]
        n10 = self.coins[10]
        n5 = self.coins[5]
        best = None
        for c25 in range(min(n25, amount // 25), -1, -1):
            rem25 = amount - 25 * c25
            for c10 in range(min(n10, rem25 // 10), -1, -1):
                rem = rem25 - 10 * c10
                if rem % 5 == 0 and rem // 5 <= n5:
                    total = c25 + c10 + rem // 5
                    if best is None or total < best[0]:
                        best = (total, c25, c10, rem // 5)
        if best is None:
            return None
        _, c25, c10, c5 = best
        return [25] * c25 + [10] * c10 + [5] * c5

    def select(self, item):
        if item not in self.prices:
            return 'UNKNOWN'
        price = self.prices[item]
        paid = self.balance()
        if paid < price:
            return 'INSUFFICIENT'
        change = self._make_change(paid - price)
        if change is None:
            return 'NO_CHANGE'
        for coin in self._inserted:
            self.coins[coin] += 1
        for coin in change:
            self.coins[coin] -= 1
        self._inserted = []
        return change

    def cancel(self):
        refund = list(self._inserted)
        self._inserted = []
        return refund
