class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)

    def __init__(self, prices, coins):
        self.prices = dict(prices)
        self.coins = {c: n for c, n in dict(coins).items() if n > 0}
        self.inserted = []

    def insert(self, coin):
        if coin not in self.ACCEPTED_COINS:
            return False
        self.inserted.append(coin)
        return True

    def balance(self):
        return sum(self.inserted)

    def cancel(self):
        returned = self.inserted
        self.inserted = []
        return returned

    def select(self, item):
        if item not in self.prices:
            return 'UNKNOWN'

        price = self.prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'

        change_amount = bal - price
        change = self._make_change(change_amount)
        if change is None:
            return 'NO_CHANGE'

        for coin in self.inserted:
            self.coins[coin] = self.coins.get(coin, 0) + 1
        for coin in change:
            self.coins[coin] -= 1
            if self.coins[coin] == 0:
                del self.coins[coin]
        self.inserted = []
        return change

    def _make_change(self, amount):
        """Return the fewest coins from inventory summing to amount, or None."""
        denoms = sorted((d for d, n in self.coins.items() if n > 0 and d > 0),
                        reverse=True)
        memo = {}

        def solve(i, amt):
            if amt == 0:
                return []
            if i == len(denoms):
                return None
            key = (i, amt)
            if key in memo:
                return memo[key]
            d = denoms[i]
            avail = self.coins[d]
            best = None
            for k in range(min(avail, amt // d), -1, -1):
                sub = solve(i + 1, amt - k * d)
                if sub is not None:
                    candidate = [d] * k + sub
                    if best is None or len(candidate) < len(best):
                        best = candidate
            memo[key] = best
            return best

        return solve(0, amount)
