from collections import Counter


class VendingMachine:
    ACCEPTED = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = Counter(dict(coins))
        self._inserted = []

    def insert(self, coin):
        if coin not in self.ACCEPTED:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        total = self.balance()
        if total < price:
            return 'INSUFFICIENT'
        change = self._make_change(total - price)
        if change is None:
            return 'NO_CHANGE'
        for coin in change:
            self._inventory[coin] -= 1
        for coin in self._inserted:
            self._inventory[coin] += 1
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount):
        if amount == 0:
            return []
        if amount < 0 or amount % 5 != 0:
            return None
        inv25 = self._inventory[25]
        inv10 = self._inventory[10]
        inv5 = self._inventory[5]
        best = None
        best_count = None
        for q in range(min(inv25, amount // 25), -1, -1):
            rem1 = amount - 25 * q
            for d in range(min(inv10, rem1 // 10), -1, -1):
                rem2 = rem1 - 10 * d
                n5 = rem2 // 5
                if n5 > inv5:
                    continue
                count = q + d + n5
                if best_count is None or count < best_count:
                    best_count = count
                    best = [25] * q + [10] * d + [5] * n5
        return best
