def color_graph(nodes, edges, k, precolored=None):
    """
    Return a dict mapping every node to a color in range(k) so that adjacent
    nodes get different colors, keeping any precolored nodes fixed.
    Return None if no such coloring exists.
    """
    if precolored is None:
        precolored = {}

    # Build adjacency sets, including any nodes that appear only in edges or precolored.
    adj = {n: set() for n in nodes}
    for u, v in edges:
        if u == v:
            return None  # a self-loop can never be properly colored
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)
    for n in precolored:
        adj.setdefault(n, set())

    if not adj:
        return {}
    if k <= 0:
        return None

    coloring = {}
    for n, c in precolored.items():
        if not isinstance(c, int) or not (0 <= c < k):
            return None
        coloring[n] = c

    # Verify the precolored assignment is itself proper.
    for n, c in coloring.items():
        for m in adj[n]:
            if m in coloring and coloring[m] == c:
                return None

    def options(n):
        forbidden = {coloring[m] for m in adj[n] if m in coloring}
        return [c for c in range(k) if c not in forbidden]

    def solve():
        uncolored = [n for n in adj if n not in coloring]
        if not uncolored:
            return True

        # Choose the most constrained node (fewest options), breaking ties by degree.
        best = None
        best_opts = None
        for n in uncolored:
            opts = options(n)
            if best is None or len(opts) < len(best_opts) or (
                len(opts) == len(best_opts) and len(adj[n]) > len(adj[best])
            ):
                best, best_opts = n, opts
                if not opts:
                    return False

        for c in best_opts:
            coloring[best] = c
            if solve():
                return True
            del coloring[best]
        return False

    if solve():
        return dict(coloring)
    return None
