def color_graph(nodes, edges, k, precolored=None):
    """
    Return a dict mapping every node to a color in 0..k-1 such that adjacent
    nodes receive different colors and precolored nodes keep their given colors.
    Return None if no such coloring exists.
    """
    precolored = dict(precolored) if precolored else {}

    # Collect every node, including those that appear only in edges or precolored.
    all_nodes = []
    seen = set()
    for v in list(nodes) + list(precolored.keys()):
        if v not in seen:
            seen.add(v)
            all_nodes.append(v)

    adj = {v: set() for v in all_nodes}
    for edge in edges:
        u, v = edge
        if u == v:
            return None  # a self-loop can never be properly colored
        for x in (u, v):
            if x not in adj:
                adj[x] = set()
                all_nodes.append(x)
        adj[u].add(v)
        adj[v].add(u)

    if not all_nodes:
        return {}
    if k <= 0:
        return None

    # Validate precolored assignments.
    for v, c in precolored.items():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None
    for v, c in precolored.items():
        for w in adj[v]:
            if w in precolored and precolored[w] == c:
                return None

    color = dict(precolored)
    all_colors = set(range(k))

    def available(v):
        used = {color[w] for w in adj[v] if w in color}
        return all_colors - used

    def solve():
        uncolored = [v for v in all_nodes if v not in color]
        if not uncolored:
            return True

        # Most-constrained-variable heuristic: pick the node with fewest options,
        # breaking ties by highest number of uncolored neighbors.
        best = None
        best_key = None
        for v in uncolored:
            avail = available(v)
            if not avail:
                return False
            uncolored_deg = sum(1 for w in adj[v] if w not in color)
            key = (len(avail), -uncolored_deg)
            if best_key is None or key < best_key:
                best_key = key
                best = (v, avail)

        v, avail = best
        for c in sorted(avail):
            color[v] = c
            if solve():
                return True
            del color[v]
        return False

    if solve():
        return {v: color[v] for v in all_nodes}
    return None
