import string

def file_name_check(name):
    if name.count('.') != 1:
        return 'No'

    prefix, extension = name.split('.')

    digits = string.digits
    letters = string.ascii_letters

    if sum(c in digits for c in name) > 3:
        return 'No'

    if not prefix or prefix[0] not in letters:
        return 'No'

    if extension not in ('txt', 'exe', 'dll'):
        return 'No'

    return 'Yes'
