def parse_kv(line):
    """Parse a config line like 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons. Semicolons inside double-quoted
      values do not split pairs.
    - 'key=value' maps to the string value.
    - A bare key (no '=') maps to True.
    - Double-quoted values have their quotes removed. Inside quotes, a
      backslash escapes the following character (e.g. \\" or \\\\).
    - Raises ValueError if a quoted value is unterminated.
    """
    segments = []
    current = []
    in_quotes = False
    escape = False

    for ch in line:
        if escape:
            current.append(ch)
            escape = False
        elif in_quotes and ch == "\\":
            current.append(ch)
            escape = True
        elif ch == '"':
            current.append(ch)
            in_quotes = not in_quotes
        elif ch == ";" and not in_quotes:
            segments.append("".join(current))
            current = []
        else:
            current.append(ch)

    if in_quotes:
        raise ValueError("unterminated quoted value in config line")
    if escape:
        raise ValueError("dangling escape at end of config line")

    segments.append("".join(current))

    result = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue

        key, sep, value = segment.partition("=")
        key = key.strip()
        if not sep:
            result[key] = True
            continue

        value = value.strip()
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = _unquote(value[1:-1])
        result[key] = value

    return result


def _unquote(text):
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == "\\" and i + 1 < len(text):
            out.append(text[i + 1])
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)
```

