import csv
import io


def column_stats(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))

    # Skip any leading blank lines before the header row.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [name.strip() for name in row]
            break

    if header is None or column not in header:
        raise KeyError(f"Column {column!r} not found in CSV header")

    index = header.index(column)

    values = []
    for row in reader:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        try:
            value = int(cell)
        except ValueError:
            value = float(cell)
        values.append(value)

