def column_stats(csv_text, column):
    """Return count, sum, mean, min and max for a numeric CSV column.

    The first non-blank row of csv_text is treated as the header, so
    leading blank lines are ignored. Empty cells (including whitespace-only
    cells) are skipped. If no numeric values are found, sum is 0 and mean,
    min and max are None.
    """
    reader = csv.reader(io.StringIO(csv_text))

    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = row
            break

    if header is None or column not in header:
        raise KeyError(f"Column {column!r} not found in CSV header")

    index = header.index(column)

    values = []
    for row in reader:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        try:
            num = int(cell)
        except ValueError:
            num = float(cell)
        values.append(num)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
