def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in " \t\r\n\f\v":
            i += 1
        elif "0" <= c <= "9":
            start = i
            while i < n and "0" <= text[i] <= "9":
                i += 1
            tokens.append(("NUM", int(text[start:i])))
        elif c in "+-*/%^()":
            tokens.append((c, c))
            i += 1
        else:
            raise SyntaxError(f"Invalid character {c!r} at position {i}")
    return tokens


def _c_div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _c_mod(a, b):
    if b == 0:
        raise ZeroDivisionError("modulo by zero")
    return a - b * _c_div(a, b)


def _c_pow(base, exp):
    if exp >= 0:
        return base ** exp
    # Negative exponent with integer (truncating) semantics.
    if base == 0:
        raise ZeroDivisionError("zero raised to a negative power")
    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1
    # |base| >= 2: 1 / base**|exp| truncates toward zero to 0.
    return 0


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos][0] if self.pos < len(self.tokens) else None

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise SyntaxError("Empty expression")
        value = self._expr()
        if self.pos != len(self.tokens):
            raise SyntaxError(f"Unexpected token {self.tokens[self.pos][1]!r}")
        return value

    # expr := term (('+' | '-') term)*
    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._advance()[0]
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def _term(self):
        value = self._unary()
        while self._peek() in ("*", "/", "%"):
            op = self._advance()[0]
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _c_div(value, rhs)
            else:
                value = _c_mod(value, rhs)
        return value

    # unary := '-' unary | power
    def _unary(self):
        if self._peek() == "-":
            self._advance()
            return -self._unary()
        return self._power()

    # power := atom ('^' unary)?   (right-associative)
    def _power(self):
        base = self._atom()
        if self._peek() == "^":
            self._advance()
            exp = self._unary()
            return _c_pow(base, exp)
        return base

    # atom := NUMBER | '(' expr ')'
    def _atom(self):
        kind = self._peek()
        if kind == "NUM":
            return self._advance()[1]
        if kind == "(":
            self._advance()
            value = self._expr()
            if self._peek() != ")":
                raise SyntaxError("Expected ')'")
            self._advance()
            return value
        if kind is None:
            raise SyntaxError("Unexpected end of expression")
        raise SyntaxError(f"Unexpected token {self.tokens[self.pos][1]!r}")


def evaluate(expr):
    """Evaluate an integer arithmetic expression.

    Supports + - * / % ^, unary minus, and parentheses. Division and
    modulo truncate toward zero (C-style). Raises SyntaxError on
    malformed input.
    """
    if not isinstance(expr, str):
        raise TypeError("expr must be a string")
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()
