        # used to make change within this same transaction.
        stock = dict(self.coins)
        for c in self._inserted:
            stock[c] = stock.get(c, 0) + 1
        change = self._make_change(bal - price, stock)
        if change is None:
            return 'NO_CHANGE'
        for c in change:
            stock[c] -= 1
        self.coins = stock
        self._inserted = []
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    def _make_change(self, amount, stock):
        denoms = sorted(v for v, c in stock.items() if c > 0)
        n = len(denoms)
        INF = float('inf')
        dp = [[INF] * (amount + 1) for _ in range(n + 1)]
        take = [[0] * (amount + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i, v in enumerate(denoms, 1):
            cnt = stock[v]
            for a in range(amount + 1):
                for k in range(min(cnt, a // v) + 1):
                    prev = dp[i - 1][a - k * v]
                    if prev + k < dp[i][a]:
                        dp[i][a] = prev + k
                        take[i][a] = k
        if dp[n][amount] == INF:
            return None
        change = []
        a = amount
        for i in range(n, 0, -1):
            k = take[i][a]
            change.extend([denoms[i - 1]] * k)
            a -= k * denoms[i - 1]
        change.sort(reverse=True)
        return change
