        self._prices = dict(prices)
        self._inventory = Counter({c: n for c, n in dict(coins).items() if n > 0})
        self._inserted = []  # coins inserted for the current transaction, in order

    def insert(self, coin):
        if coin not in VALID_COINS:
            return False
        self._inserted.append(coin)
        return True

    def balance(self):
        return sum(self._inserted)

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        return returned

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return 'INSUFFICIENT'
        # Coins the customer just inserted can also be used as change.
        pool = self._inventory + Counter(self._inserted)
        change = self._make_change(bal - price, pool)
        if change is None:
            return 'NO_CHANGE'
        # Commit the transaction: the pool (inventory + inserted coins)
        # minus the change becomes the new inventory.
        for c in change:
            pool[c] -= 1
        self._inventory = Counter({c: n for c, n in pool.items() if n > 0})
        self._inserted = []
        return change

    def _make_change(self, amount, pool):
        """Return the fewest coins from pool summing to amount, or None."""
        if amount == 0:
            return []

        # Expand the pool into individual coin units (0/1 knapsack).
        units = []
        for coin, count in sorted(pool.items()):
            units.extend([coin] * count)
        n = len(units)

        INF = float('inf')
        # dp[i][a] = minimum number of units among the first i units summing to a
        dp = [[INF] * (amount + 1) for _ in range(n + 1)]
        dp[0][0] = 0
        for i in range(1, n + 1):
            v = units[i - 1]
            prev = dp[i - 1]
            row = dp[i]
            for a in range(amount + 1):
                best = prev[a]
                if a >= v and prev[a - v] + 1 < best:
                    best = prev[a - v] + 1
                row[a] = best

        if dp[n][amount] == INF:
            return None

        # Reconstruct the chosen coins.
        result = []
        a = amount
        for i in range(n, 0, -1):
            if dp[i][a] == dp[i - 1][a]:
                continue
            v = units[i - 1]
            result.append(v)
            a -= v
        return sorted(result, reverse=True)
