        if item not in self._prices:
            return 'UNKNOWN'
        price = self._prices[item]
        total = self.balance()
        if total < price:
            return 'INSUFFICIENT'
        # Inserted coins are available to make change along with the inventory.
        available = self._inventory + Counter(self._inserted)
        change = self._make_change(total - price, available)
        if change is None:
            return 'NO_CHANGE'
        for coin in change:
            available[coin] -= 1
        self._inventory = available
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount, available):
        if amount == 0:
            return []
        if amount < 0 or amount % 5 != 0:
            return None
        inv25 = available[25]
        inv10 = available[10]
        inv5 = available[5]
        best = None
        best_count = None
        for q in range(min(inv25, amount // 25), -1, -1):
            rem1 = amount - 25 * q
            for d in range(min(inv10, rem1 // 10), -1, -1):
                rem2 = rem1 - 10 * d
                n5 = rem2 // 5
                if n5 > inv5:
                    continue
                count = q + d + n5
                if best_count is None or count < best_count:
                    best_count = count
                    best = [25] * q + [10] * d + [5] * n5
        return best
