def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines in the input and
    are kept separate in the output, joined by a single blank line. Words
    longer than width are broken into width-sized pieces; the final piece
    of a broken word can then share a line with following words.
    """
    if width <= 0:
        raise ValueError("width must be positive")

    # Split into paragraphs on blank (or whitespace-only) lines.
    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        else:
            if current:
                paragraphs.append(" ".join(current))
                current = []
    if current:
        paragraphs.append(" ".join(current))

    wrapped_paragraphs = []
    for para in paragraphs:
        words = para.split()
        lines = []
        line = ""
        for word in words:
            if line and len(line) + 1 + len(word) <= width:
                line += " " + word
                continue

            # The word doesn't fit on the current line; flush it.
            if line:
                lines.append(line)
                line = ""

            # Break over-long words into width-sized pieces.
            while len(word) > width:
                lines.append(word[:width])
                word = word[width:]
            line = word

        if line:
            lines.append(line)
        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)
