import re


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by one or more blank lines and are wrapped
    independently. Within a paragraph, all whitespace runs are collapsed
    to single spaces. Words longer than width are split into pieces of
    at most width characters, and those pieces are wrapped greedily like
    ordinary words. Paragraphs are joined by a single blank line.
    """
    if width <= 0:
        raise ValueError("width must be positive")

    paragraphs = re.split(r"\n\s*\n", text.strip())
    wrapped_paragraphs = []

    for paragraph in paragraphs:
        words = paragraph.split()
        if not words:
            continue

        pieces = []
        for word in words:
            for i in range(0, len(word), width):
                pieces.append(word[i:i + width])

        lines = []
        current = ""
        for piece in pieces:
            if not current:
                current = piece
            elif len(current) + 1 + len(piece) <= width:
                current += " " + piece
            else:
                lines.append(current)
                current = piece
        if current:
            lines.append(current)

        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)
