def tri(n: int) -> list[int]:
    if n < 0:
        return []

    def direct(k: int) -> int:
        # Value of t(k) for k == 0, 1, or even k >= 2 (no recursion needed).
        if k == 0:
            return 1
        if k == 1:
            return 3
        return 1 + k // 2

    res: list[int] = []
    for k in range(n + 1):
        if k <= 1 or k % 2 == 0:
            res.append(direct(k))
        else:
            # k is odd and >= 3: t(k) = t(k-1) + t(k-2) + t(k+1)
            # t(k-1) is even and t(k-2) is odd, both already computed.
            # t(k+1) is even and defined directly.
            res.append(res[k - 1] + res[k - 2] + direct(k + 1))
    return res
