def tri(n: int) -> list[int]:
    if n < 0:
        return []
    t = [0] * (n + 1)
    for k in range(n + 1):
        if k == 0:
            t[k] = 1
        elif k == 1:
            t[k] = 3
        elif k % 2 == 0:
            t[k] = 1 + k // 2
        else:
            # t(k+1) is even, so it is given directly by the closed form.
            t[k] = t[k - 1] + t[k - 2] + (1 + (k + 1) // 2)
    return t
