def do_algebra(operators: list[str], operands: list[int]) -> int:
    precedence = {"+": 1, "-": 1, "*": 2, "//": 2, "**": 3}
    right_assoc = {"**"}

    def apply(op: str, left: int, right: int) -> int:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "//":
            return left // right
        if op == "**":
            return left ** right
        raise ValueError(f"Unknown operator: {op}")

    value_stack: list[int] = [operands[0]]
    op_stack: list[str] = []

    for op, operand in zip(operators, operands[1:]):
        while op_stack:
            top = op_stack[-1]
            if precedence[top] > precedence[op] or (
                precedence[top] == precedence[op] and op not in right_assoc
            ):
                right = value_stack.pop()
                left = value_stack.pop()
                value_stack.append(apply(op_stack.pop(), left, right))
            else:
                break
        op_stack.append(op)
        value_stack.append(operand)

    while op_stack:
        right = value_stack.pop()
        left = value_stack.pop()
        value_stack.append(apply(op_stack.pop(), left, right))

    return value_stack[0]
```

