def parse_kv(line):
    """Parse a config line like 'a=1; debug; msg="hi; there"' into a dict.

    Bare keys map to True. Double-quoted values may contain semicolons.
    Raises ValueError on an unterminated quoted value or an empty key.
    """
    parts = []
    current = []
    in_quotes = False

    for ch in line:
        if ch == '"':
            in_quotes = not in_quotes
            current.append(ch)
        elif ch == ';' and not in_quotes:
            parts.append(''.join(current))
            current = []
        else:
            current.append(ch)

    if in_quotes:
        raise ValueError("unterminated quoted value")

    parts.append(''.join(current))

    result = {}
    for part in parts:
        part = part.strip()
        if not part:
            continue

        if '=' in part:
            key, _, value = part.partition('=')
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError("empty key in entry: %r" % part)
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            result[key] = value
        else:
            if '"' in part:
                raise ValueError("unexpected quote in bare key: %r" % part)
            result[part] = True

    return result
```

