def do_algebra(operators: list[str], operands: list[int]) -> int:
    precedence = {"+": 1, "-": 1, "*": 2, "//": 2, "**": 3}
    right_associative = {"**"}

    values = [operands[0]]
    pending_ops = []

    def apply_top():
        op = pending_ops.pop()
        b = values.pop()
        a = values.pop()
        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "//":
            result = a // b
        elif op == "**":
            result = a ** b
        else:
            raise ValueError(f"Unknown operator: {op}")
        values.append(result)

    for op, operand in zip(operators, operands[1:]):
        while pending_ops and (
            precedence[pending_ops[-1]] > precedence[op]
            or (
                precedence[pending_ops[-1]] == precedence[op]
                and op not in right_associative
            )
        ):
            apply_top()
        pending_ops.append(op)
        values.append(operand)

    while pending_ops:
        apply_top()

    return values[0]
