def compress(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        j = i
        while j < n and s[j] == ch:
            j += 1
        run = j - i
        result.append(ch)
        if run > 1:
            result.append(str(run))
        i = j
    return "".join(result)


def decompress(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        i += 1
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j > i:
            count = int(s[i:j])
        else:
            count = 1
        result.append(ch * count)
        i = j
    return "".join(result)
```

