def to_roman(n: int) -> str:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("input must be an integer in the range 1..3999")
    if n < 1 or n > 3999:
        raise ValueError("input must be in the range 1..3999")
    parts = []
    for value, symbol in _ROMAN_VALUES:
        count, n = divmod(n, value)
        parts.append(symbol * count)
    return "".join(parts)


def from_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("invalid Roman numeral")
    # Accept only canonical forms: the only way to be canonical is to
    # round-trip exactly through to_roman.
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in _ROMAN_DIGIT_VALUES:
            raise ValueError(f"invalid Roman numeral: {s!r}")
        val = _ROMAN_DIGIT_VALUES[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    if total < 1 or total > 3999:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    if to_roman(total) != s:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    return total
