import re

_ROMAN_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_SYMBOL_VALUES = {
    "I": 1, "V": 5, "X": 10, "L": 50,
    "C": 100, "D": 500, "M": 1000,
}

_CANONICAL_RE = re.compile(
    r"M{0,3}(?:CM|CD|D?C{0,3})(?:XC|XL|L?X{0,3})(?:IX|IV|V?I{0,3})"
)


def to_roman(n: int) -> str:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"expected an int in range 1..3999, got {n!r}")
    if not 1 <= n <= 3999:
        raise ValueError(f"value out of range 1..3999: {n}")

    parts = []
    remaining = n
    for value, symbol in _ROMAN_VALUES:
        count, remaining = divmod(remaining, value)
        parts.append(symbol * count)
    return "".join(parts)


def from_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    if _CANONICAL_RE.fullmatch(s) is None:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _SYMBOL_VALUES[ch]
        if i + 1 < len(s) and value < _SYMBOL_VALUES[s[i + 1]]:
            total -= value
        else:
            total += value

    # Round-trip check guarantees the string is exactly the canonical form.
    if to_roman(total) != s:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    return total
