def parse_kv(line: str) -> dict:
    result = {}
    i = 0
    n = len(line)

    while i < n:
        # Read the key: everything up to the first '=' or ';'.
        start = i
        while i < n and line[i] not in ";=":
            i += 1
        key = line[start:i].strip()

        # Bare key (or empty item) terminated by ';' or end of input.
        if i >= n or line[i] == ";":
            if key:
                result[key] = True
            i += 1
            continue

        # line[i] == '=': parse the value.
        i += 1
        j = i
        while j < n and line[j].isspace():
            j += 1

        if j < n and line[j] == '"':
            # Quoted value: ';' is literal, \" and \\ are escapes.
            j += 1
            buf = []
            closed = False
            while j < n:
                c = line[j]
                if c == "\\" and j + 1 < n and line[j + 1] in ('"', "\\"):
                    buf.append(line[j + 1])
                    j += 2
                elif c == '"':
                    closed = True
                    j += 1
                    break
                else:
                    buf.append(c)
                    j += 1
            if not closed:
                raise ValueError("unterminated quoted value")

            # Only whitespace may follow the closing quote before ';' or end.
            while j < n and line[j].isspace():
                j += 1
            if j < n and line[j] != ";":
                raise ValueError("unexpected characters after quoted value")
            value = "".join(buf)
            i = j + 1
        else:
            # Unquoted value: runs until the next ';', stripped of whitespace.
            end = line.find(";", i)
            if end == -1:
                end = n
            value = line[i:end].strip()
            i = end + 1

        result[key] = value

    return result
