import csv
import io


def column_stats(csv_text: str, column: str) -> dict:
    reader = csv.reader(io.StringIO(csv_text))
    target = column.strip()
    header = None
    idx = None
    values = []

    for row in reader:
        # Skip blank lines (csv yields [] for them, or a single whitespace cell).
        if len(row) == 0 or (len(row) == 1 and row[0].strip() == ""):
            continue

        if header is None:
            header = [h.strip() for h in row]
            if target not in header:
                raise KeyError(column)
            idx = header.index(target)
            continue

        if idx >= len(row):
            continue  # short row: the cell is missing, so treat it as empty

        cell = row[idx].strip()
        if cell == "":
            continue

        try:
            values.append(float(cell))
        except ValueError:
            raise ValueError(f"non-numeric value in column {column!r}: {cell!r}")

    if header is None or target not in header:
        raise KeyError(column)

    if not values:
        return {"count": 0, "sum": 0.0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": len(values),
        "sum": total,
        "mean": total / len(values),
        "min": min(values),
        "max": max(values),
    }
