from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._ttl = ttl
        # Maps key -> (value, expiry_time); ordered from least to most recently used.
        self._data = OrderedDict()

    @staticmethod
    def _is_expired(expiry: float, now: float) -> bool:
        return now >= expiry

    def _purge_expired(self, now: float) -> None:
        expired_keys = [
            k for k, (_, expiry) in self._data.items()
            if self._is_expired(expiry, now)
        ]
        for k in expired_keys:
            del self._data[k]

    def put(self, key, value, now: float) -> None:
        expiry = now + self._ttl
        if key in self._data:
            # Overwrite: never evicts, resets expiry, becomes most recently used.
            self._data[key] = (value, expiry)
            self._data.move_to_end(key)
            return

        # Inserting a new key.
        if len(self._data) >= self._capacity:
            self._purge_expired(now)
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)  # evict least recently used

        self._data[key] = (value, expiry)

    def get(self, key, now: float):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expiry = entry
        if self._is_expired(expiry, now):
            del self._data[key]
            return None
        # Mark as most recently used; do not extend expiry.
        self._data.move_to_end(key)
        return value

    def size(self, now: float) -> int:
        return sum(
            1 for _, expiry in self._data.values()
            if not self._is_expired(expiry, now)
        )
