import csv
import io
import math


def column_stats(csv_text: str, column: str) -> dict:
    def is_blank(row):
        return not row or (len(row) == 1 and not row[0].strip())

    reader = csv.reader(io.StringIO(csv_text))

    header = None
    for row in reader:
        if is_blank(row):
            continue
        header = [cell.strip() for cell in row]
        break

    if header is None or column not in header:
        raise KeyError(column)

    idx = header.index(column)

    values = []
    for row in reader:
        if is_blank(row):
            continue
        cell = row[idx].strip() if idx < len(row) else ""
        if not cell:
            continue
        try:
            values.append(float(cell))
        except ValueError:
            raise ValueError(
                f"non-numeric value {cell!r} in column {column!r}"
            ) from None

    if not values:
        return {"count": 0, "sum": 0.0, "mean": None, "min": None, "max": None}

    total = math.fsum(values)
    return {
        "count": len(values),
        "sum": total,
        "mean": total / len(values),
        "min": min(values),
        "max": max(values),
    }
```

