from collections import OrderedDict


class TTLCache:
    """An LRU cache whose entries expire after a fixed time-to-live.

    Time is supplied explicitly by the caller via the `now` argument.
    """

    def __init__(self, capacity: int, ttl: float) -> None:
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._ttl = ttl
        # key -> (value, expires_at); ordered from least to most recently used.
        self._data: "OrderedDict[object, tuple]" = OrderedDict()

    @staticmethod
    def _is_expired(expires_at: float, now: float) -> bool:
        return now >= expires_at

    def _purge_expired(self, now: float) -> None:
        expired_keys = [
            k for k, (_, exp) in self._data.items() if self._is_expired(exp, now)
        ]
        for k in expired_keys:
            del self._data[k]

    def put(self, key, value, now: float) -> None:
        expires_at = now + self._ttl

        if key in self._data:
            # Overwrite: never evicts, resets expiry, marks most recently used.
            self._data[key] = (value, expires_at)
            self._data.move_to_end(key)
            return

        # Inserting a new key.
        if len(self._data) >= self._capacity:
            self._purge_expired(now)
            if len(self._data) >= self._capacity:
                # Evict least recently used entry.
                self._data.popitem(last=False)

        self._data[key] = (value, expires_at)

    def get(self, key, now: float):
        entry = self._data.get(key)
        if entry is None:
            return None

        value, expires_at = entry
        if self._is_expired(expires_at, now):
            del self._data[key]
            return None

        # Mark as most recently used; expiry is NOT extended.
        self._data.move_to_end(key)
        return value

    def size(self, now: float) -> int:
        return sum(
            1 for _, expires_at in self._data.values()
            if not self._is_expired(expires_at, now)
        )
