        if tok is None:
            raise SyntaxError("unexpected end of expression")
        if '0' <= tok[0] <= '9':
            self._advance()
            return ('num', int(tok))
        if tok == '(':
            self._advance()
            node = self._expr()
            if self._peek() != ')':
