class VendingMachine:
    ACCEPTED = (5, 10, 25)

    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory = {d: 0 for d in self.ACCEPTED}
        for denom, count in coins.items():
            self._inventory[denom] = self._inventory.get(denom, 0) + count
        self._balance = 0
        self._transaction = []  # coins inserted since last successful select/cancel

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED:
            return False
        self._balance += coin
        self._inventory[coin] = self._inventory.get(coin, 0) + 1
        self._transaction.append(coin)
        return True

    def balance(self) -> int:
        return self._balance

    def _find_change(self, amount: int):
        """Return the minimal-coin list of change for amount using inventory, or None."""
        if amount < 0:
            return None
        if amount == 0:
            return []
        if amount % 5 != 0:
            return None

        inv25 = self._inventory.get(25, 0)
        inv10 = self._inventory.get(10, 0)
        inv5 = self._inventory.get(5, 0)

        best = None
        best_count = None
        for a in range(min(inv25, amount // 25), -1, -1):
            r = amount - 25 * a
            for b in range(min(inv10, r // 10), -1, -1):
                r2 = r - 10 * b
                c = r2 // 5
                if c > inv5:
                    continue
                count = a + b + c
                if best_count is None or count < best_count:
                    best_count = count
                    best = (a, b, c)
        if best is None:
            return None
        a, b, c = best
        return [25] * a + [10] * b + [5] * c

    def select(self, item: str):
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        if self._balance < price:
            return "INSUFFICIENT"
        change = self._find_change(self._balance - price)
        if change is None:
            return "NO_CHANGE"
        for coin in change:
            self._inventory[coin] -= 1
        self._balance = 0
        self._transaction = []
        return sorted(change, reverse=True)

    def cancel(self) -> list[int]:
        returned = sorted(self._transaction, reverse=True)
        for coin in returned:
            self._inventory[coin] -= 1
        self._balance = 0
        self._transaction = []
        return returned
