class VendingMachine:
    ACCEPTED = (5, 10, 25)

    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory = {d: c for d, c in coins.items()}
        self._txn = []  # coins inserted since last successful select or cancel

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED:
            return False
        self._txn.append(coin)
        self._inventory[coin] = self._inventory.get(coin, 0) + 1
        return True

    def balance(self) -> int:
        return sum(self._txn)

    def _make_change(self, amount: int):
        """Return the fewest coins (sorted descending) summing to amount using
        the current inventory, or None if impossible."""
        denoms = [(d, c) for d, c in self._inventory.items() if d > 0 and c > 0]
        n = len(denoms)
        INF = float("inf")
        best = [[INF] * (amount + 1) for _ in range(n + 1)]
        choice = [[0] * (amount + 1) for _ in range(n + 1)]
        best[0][0] = 0
        for i in range(1, n + 1):
            d, c = denoms[i - 1]
            for v in range(amount + 1):
                for t in range(0, min(c, v // d) + 1):
                    prev = best[i - 1][v - t * d]
                    if prev + t < best[i][v]:
                        best[i][v] = prev + t
                        choice[i][v] = t
        if best[n][amount] == INF:
            return None
        result = []
        v = amount
        for i in range(n, 0, -1):
            d = denoms[i - 1][0]
            t = choice[i][v]
            result.extend([d] * t)
            v -= t * d
        return sorted(result, reverse=True)

    def select(self, item: str):
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
