def _tokenize(expr: str) -> list:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif c in '+-*/%^()':
            tokens.append(c)
            i += 1
        else:
            raise SyntaxError(f"invalid character {c!r} at position {i}")
    return tokens


def _trunc_div(a: int, b: int) -> int:
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _trunc_mod(a: int, b: int) -> int:
    return a - b * _trunc_div(a, b)


class _Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.peek()
        self.pos += 1
        return tok

    def parse(self) -> int:
        if not self.tokens:
            raise SyntaxError("empty expression")
        value = self.expr()
        if self.peek() is not None:
            raise SyntaxError(f"unexpected token {self.peek()!r}")
        return value

    # expr := term (('+' | '-') term)*
    def expr(self) -> int:
        value = self.term()
        while self.peek() in ('+', '-'):
            op = self.advance()
            right = self.term()
            value = value + right if op == '+' else value - right
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def term(self) -> int:
        value = self.unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()
            right = self.unary()
            if op == '*':
                value = value * right
            elif op == '/':
                value = _trunc_div(value, right)
            else:
                value = _trunc_mod(value, right)
        return value

    # unary := '-' unary | power
    def unary(self) -> int:
        if self.peek() == '-':
            self.advance()
            return -self.unary()
        return self.power()

    # power := primary ('^' exponent)?    (right-associative)
    def power(self) -> int:
        base = self.primary()
        if self.peek() == '^':
            self.advance()
            exp = self.exponent()
            if exp < 0:
                raise ValueError("negative exponent is not supported")
            return base ** exp
        return base

    # exponent := '-' exponent | power
    def exponent(self) -> int:
        if self.peek() == '-':
            self.advance()
            return -self.exponent()
        return self.power()

    # primary := NUMBER | '(' expr ')'
    def primary(self) -> int:
        tok = self.peek()
        if tok is None:
            raise SyntaxError("unexpected end of expression")
        if tok == '(':
            self.advance()
            value = self.expr()
            if self.peek() != ')':
                raise SyntaxError("expected ')'")
            self.advance()
            return value
        if tok[0].isdigit():
            self.advance()
            return int(tok)
        raise SyntaxError(f"unexpected token {tok!r}")


def evaluate(expr: str) -> int:
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()
