from functools import lru_cache


class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)

    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory = {int(d): int(c) for d, c in coins.items() if int(c) > 0}
        self._balance = 0
        self._transaction = []  # coins inserted since last successful select/cancel

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED_COINS:
            return False
        self._balance += coin
        self._transaction.append(coin)
        self._inventory[coin] = self._inventory.get(coin, 0) + 1
        return True

    def balance(self) -> int:
        return self._balance

    def select(self, item: str):
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        if self._balance < price:
            return "INSUFFICIENT"
        owed = self._balance - price
        change = self._make_change(owed)
        if change is None:
            return "NO_CHANGE"
        for coin in change:
            self._inventory[coin] -= 1
        self._balance = 0
        self._transaction = []
        return sorted(change, reverse=True)

    def cancel(self) -> list[int]:
        returned = sorted(self._transaction, reverse=True)
        for coin in self._transaction:
            self._inventory[coin] -= 1
        self._balance = 0
        self._transaction = []
        return returned

    def _make_change(self, amount: int):
        """Return the minimum-count list of coins summing to amount using the
        current inventory, or None if impossible."""
        denoms = sorted(
            (d for d, c in self._inventory.items() if c > 0 and d > 0),
            reverse=True,
        )
        counts = [self._inventory[d] for d in denoms]
        n = len(denoms)
        INF = float("inf")

        @lru_cache(maxsize=None)
        def best(i: int, r: int):
            if r == 0:
                return 0
            if i == n:
                return INF
            d = denoms[i]
            result = INF
            for k in range(min(counts[i], r // d) + 1):
                sub = best(i + 1, r - k * d)
                if sub + k < result:
                    result = sub + k
            return result

        if amount < 0 or best(0, amount) == INF:
            return None

        change = []
        r = amount
        for i, d in enumerate(denoms):
            if r == 0:
                break
            target = best(i, r)
            for k in range(min(counts[i], r // d) + 1):
                if k + best(i + 1, r - k * d) == target:
                    change.extend([d] * k)
                    r -= k * d
                    break
        return change if r == 0 else None
