    def parser(s, i):
        if i < len(s) and s[i] == c:
            return (c, i + 1)
        return None
    return parser


def string(lit):
    def parser(s, i):
        if s.startswith(lit, i):
            return (lit, i + len(lit))
        return None
    return parser


def seq(*ps):
    def parser(s, i):
        values = []
        j = i
        for p in ps:
            result = p(s, j)
            if result is None:
                return None
            value, j = result
            values.append(value)
        return (values, j)
    return parser


def alt(*ps):
    def parser(s, i):
        for p in ps:
            result = p(s, i)
            if result is not None:
                return result
        return None
    return parser


def many(p):
    def parser(s, i):
        values = []
        j = i
        while True:
            result = p(s, j)
            if result is None:
                break
            value, k = result
            if k == j:
                # Non-consuming success: discard and stop to guarantee termination.
                break
            values.append(value)
            j = k
        return (values, j)
    return parser


def sep_by(p, sep):
    def parser(s, i):
        first = p(s, i)
        if first is None:
            return ([], i)
        value, j = first
        values = [value]
        while True:
            sep_result = sep(s, j)
            if sep_result is None:
                break
            _, k = sep_result
            item = p(s, k)
            if item is None:
                break
            value, j = item
            values.append(value)
        return (values, j)
    return parser


def map_(p, f):
    def parser(s, i):
        result = p(s, i)
        if result is None:
            return None
        value, j = result
        return (f(value), j)
    return parser


def parse(p, s):
    result = p(s, 0)
    if result is None:
        raise ParseError("parse failed", 0)
