from bisect import bisect_left


class Scheduler:
    """Books a single room using half-open integer intervals [start, end)."""

    def __init__(self) -> None:
        # Sorted by start. Bookings never overlap, so starts are unique and ordered.
        self._items: list[tuple[int, int]] = []

    def book(self, start: int, end: int) -> bool:
        if start >= end:
            raise ValueError("start must be less than end")

        idx = bisect_left(self._items, (start, end))

        # The previous booking overlaps if it ends after our start.
        if idx > 0 and self._items[idx - 1][1] > start:
            return False
        # The next booking overlaps if it starts before our end.
        if idx < len(self._items) and self._items[idx][0] < end:
            return False

        self._items.insert(idx, (start, end))
        return True

    def cancel(self, start: int, end: int) -> bool:
        idx = bisect_left(self._items, (start, end))
        if idx < len(self._items) and self._items[idx] == (start, end):
            del self._items[idx]
            return True
        return False

    def bookings(self) -> list[tuple[int, int]]:
        return list(self._items)

    def free_slots(self, lo: int, hi: int, min_len: int = 1) -> list[tuple[int, int]]:
        if lo >= hi:
            return []

        gaps: list[tuple[int, int]] = []
        cursor = lo

        for s, e in self._items:
            if e <= lo:
                continue
            if s >= hi:
                break
            cs = max(s, lo)
            ce = min(e, hi)
            if cs > cursor:
                gaps.append((cursor, cs))
            cursor = max(cursor, ce)

        if cursor < hi:
            gaps.append((cursor, hi))

        return [(s, e) for s, e in gaps if e - s >= min_len]
