class Scheduler:
    """Books a single room using half-open integer intervals [start, end)."""

    def __init__(self) -> None:
        # Kept sorted by (start, end). Bookings never overlap, so they are
        # also sorted by end.
        self._items: list[tuple[int, int]] = []

    def book(self, start: int, end: int) -> bool:
        if start >= end:
            raise ValueError("start must be less than end")

        idx = bisect.bisect_left(self._items, (start, end))

        # The nearest booking before the insertion point has the largest end
        # among those preceding it, so checking it is sufficient.
        if idx > 0 and self._items[idx - 1][1] > start:
            return False
        # The nearest booking at or after the insertion point has the smallest
        # start among those following it, so checking it is sufficient.
