from collections import defaultdict


def color_graph(nodes, edges, k, precolored=None):
    if precolored is None:
        precolored = {}

    # Collect every node, preserving first-seen order.
    node_list = []
    seen = set()

    def add_node(n):
        if n not in seen:
            seen.add(n)
            node_list.append(n)

    for n in nodes:
        add_node(n)

    edge_list = []
    for u, v in edges:
        if u == v:  # self-loop can never be properly colored
            return None
        add_node(u)
        add_node(v)
        edge_list.append((u, v))

    for n in precolored:
        add_node(n)

    if not node_list:
        return {}
    if not isinstance(k, int) or k < 1:
        return None

    adj = {n: set() for n in node_list}
    for u, v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    # Validate precoloring.
    assign = {}
    for n, c in precolored.items():
        if not isinstance(c, int) or c < 0 or c >= k:
            return None
        assign[n] = c
    for n, c in assign.items():
        for w in adj[n]:
            if w in assign and assign[w] == c:
                return None

    # Initial domains: colors not used by precolored neighbours.
    domains = {n: set(range(k)) for n in node_list}
    for n, c in assign.items():
        for w in adj[n]:
            if w not in assign:
                domains[w].discard(c)
    for n in node_list:
        if n not in assign and not domains[n]:
            return None

    def solve(assign, domains):
        uncolored = [n for n in node_list if n not in assign]
        if not uncolored:
            return dict(assign)

        # Most constrained variable first (fewest remaining colors).
        n = min(uncolored, key=lambda x: (len(domains[x]), -len(adj[x])))

        for c in sorted(domains[n]):
            # Forward checking: remove c from unassigned neighbours.
            new_domains = {m: set(d) for m, d in domains.items()}
            ok = True
            for w in adj[n]:
                if w not in assign:
                    new_domains[w].discard(c)
                    if not new_domains[w]:
                        ok = False
                        break
            if not ok:
                continue

            assign[n] = c
            result = solve(assign, new_domains)
            if result is not None:
                return result
            del assign[n]

        return None

    return solve(assign, domains)
