def color_graph(nodes, edges, k, precolored=None):
    if precolored is None:
        precolored = {}

    # Collect all nodes, including endpoints of edges not listed in nodes.
    all_nodes = list(dict.fromkeys(list(nodes) + [x for e in edges for x in e]))

    if k < 0:
        return None

    # Self-loops make coloring impossible.
    adj = {n: set() for n in all_nodes}
    for u, v in edges:
        if u == v:
            return None
        adj[u].add(v)
        adj[v].add(u)

    # Validate precolored entries.
    coloring = {}
    for n, c in precolored.items():
        if n not in adj:
            # Precolored node not in graph; it still must be a valid color.
            if not (isinstance(c, int) and 0 <= c < k):
                return None
            continue
        if not (isinstance(c, int) and 0 <= c < k):
            return None
        coloring[n] = c

    # Check precolorings don't conflict with each other.
    for u, v in edges:
        if u in coloring and v in coloring and coloring[u] == coloring[v]:
            return None

    if not all_nodes:
        return {}

    if k == 0:
        return None

    # Backtracking with most-constrained-variable ordering.
    def available_colors(n, col):
        used = {col[m] for m in adj[n] if m in col}
        return [c for c in range(k) if c not in used]

    def solve(col):
        uncolored = [n for n in all_nodes if n not in col]
        if not uncolored:
            return True
        # Pick uncolored node with fewest available colors.
        best = None
        best_opts = None
        for n in uncolored:
            opts = available_colors(n, col)
