        if n not in adj:
            adj[n] = set()
            order.append(n)

    for n in nodes:
        add(n)
    for u, v in edges:
        if u == v:
            return None  # self-loop can never be properly colored
        add(u)
        add(v)
        adj[u].add(v)
        adj[v].add(u)
    for n in precolored:
        add(n)

    if not order:
        return {}

