        for m in adj[n]:
            if m in precolored and precolored[m] == c:
                return None

    color = {}
    avail = {n: set(range(k)) for n in order}

    def assign(n, c, removed):
        color[n] = c
        for m in adj[n]:
            if m not in color and c in avail[m]:
                avail[m].discard(c)
                removed.append((m, c))

    def undo(n, c, removed):
        del color[n]
        for m, cc in removed:
            avail[m].add(cc)

    # Fix precolored nodes first.
    for n, c in precolored.items():
        if c not in avail[n]:
            return None
        assign(n, c, [])

    def search():
        uncolored = [n for n in order if n not in color]
        if not uncolored:
