def color_graph(nodes, edges, k, precolored=None):
    # Build undirected adjacency over all nodes, including edge endpoints
    # and precolored nodes that are not listed in `nodes`.
    adj = {}
    for n in nodes:
        adj.setdefault(n, set())

    for u, v in edges:
        if u == v:
            return None  # self-loop can never be properly colored
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    if precolored is None:
        precolored = {}

    for n, c in precolored.items():
        adj.setdefault(n, set())
        if not isinstance(c, int) or isinstance(c, bool) or not (0 <= c < k):
            return None

    if not adj:
        return {}

    if k <= 0:
        return None

    color = {}
    for n, c in precolored.items():
        color[n] = c

    # Verify precolored assignments do not conflict with each other.
    for n in color:
        for m in adj[n]:
            if m in color and color[m] == color[n]:
                return None

    # Initial domains for uncolored nodes: colors not used by colored neighbors.
    domains = {}
    for n in adj:
        if n in color:
            continue
        forbidden = {color[m] for m in adj[n] if m in color}
        dom = set(range(k)) - forbidden
        if not dom:
            return None
        domains[n] = dom

    def solve(color, domains):
        uncolored = [n for n in adj if n not in color]
        if not uncolored:
            return True

        # Most constrained variable first (fewest remaining colors, then highest degree).
        n = min(uncolored, key=lambda x: (len(domains[x]), -len(adj[x])))

        for c in sorted(domains[n]):
            color[n] = c
            new_domains = {m: set(domains[m]) for m in uncolored if m != n}
            ok = True
            for m in adj[n]:
                if m in new_domains:
                    new_domains[m].discard(c)
                    if not new_domains[m]:
                        ok = False
                        break
            if ok and solve(color, new_domains):
                return True
            del color[n]

        return False

    if solve(color, domains):
        return {n: color[n] for n in adj}
    return None
