def wrap_text(text: str, width: int) -> str:
    if width < 1:
        raise ValueError("width must be at least 1")

    # Group lines into paragraphs; blank (or whitespace-only) lines separate them.
    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip() == "":
            if current:
                paragraphs.append(current)
                current = []
        else:
            current.append(line)
    if current:
        paragraphs.append(current)

    output_paragraphs = []
    for para_lines in paragraphs:
        # Words are separated by any run of whitespace, including newlines.
        words = []
        for word in " ".join(para_lines).split():
            # Split overlong words into pieces of exactly `width` characters.
            while len(word) > width:
                words.append(word[:width])
                word = word[width:]
            words.append(word)

        # Greedy wrapping.
        lines = []
        cur = ""
        for word in words:
            if not cur:
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)

        output_paragraphs.append(lines)

    # Separate paragraphs with exactly one empty line.
    all_lines = []
    for i, lines in enumerate(output_paragraphs):
        if i > 0:
            all_lines.append("")
        all_lines.extend(lines)

    return "\n".join(all_lines)
