import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Normalize: every package is a node; duplicate dependency entries collapse.
    graph: dict[str, set[str]] = {}
    for pkg, requires in deps.items():
        graph.setdefault(pkg, set()).update(requires)
        for r in requires:
            graph.setdefault(r, set())

    # Reverse edges and in-degrees (number of distinct unplaced dependencies).
    dependents: dict[str, list[str]] = {n: [] for n in graph}
    indegree: dict[str, int] = {}
    for node, requires in graph.items():
        indegree[node] = len(requires)
        for r in requires:
            dependents[r].append(node)

    # Kahn's algorithm with a min-heap gives the lexicographically smallest order.
    heap = [n for n, d in indegree.items() if d == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for dep in dependents[node]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(order) == len(graph):
        return order

    # Some packages remain unplaced. Every remaining package has at least one
    # remaining dependency, so walking along remaining dependencies must
    # eventually revisit a package, which closes a cycle.
    placed = set(order)
    remaining = [n for n in graph if n not in placed]
    x = min(remaining)
    path: list[str] = []
    index: dict[str, int] = {}
    while x not in index:
        index[x] = len(path)
        path.append(x)
        x = min(d for d in graph[x] if d not in placed)
    cycle = path[index[x]:] + [x]
    raise CycleError(cycle)
