    nodes = set(deps)
    adj = {}
    for pkg, dep_list in deps.items():
        adj[pkg] = sorted(set(dep_list))
        nodes.update(dep_list)
    for n in nodes:
        adj.setdefault(n, [])

    # Cycle detection: iterative DFS with three states.
    # state absent = unvisited, 1 = on current path, 2 = fully explored.
    state = {}
    for root in sorted(nodes):
        if root in state:
            continue
        state[root] = 1
        path = [root]
        stack = [(root, iter(adj[root]))]
        while stack:
            node, it = stack[-1]
            nxt = next(it, None)
            if nxt is None:
                state[node] = 2
                stack.pop()
                path.pop()
                continue
            s = state.get(nxt)
            if s == 1:
                idx = path.index(nxt)
                raise CycleError(path[idx:] + [nxt])
            if s is None:
                state[nxt] = 1
                path.append(nxt)
                stack.append((nxt, iter(adj[nxt])))

