import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    graph = {}
    nodes = set(deps)
    for pkg, requires in deps.items():
        graph[pkg] = set(requires)
        nodes.update(requires)
    for node in nodes:
        graph.setdefault(node, set())

    dependents = {node: [] for node in nodes}
    indegree = {}
    for node in nodes:
        indegree[node] = len(graph[node])
        for dep in graph[node]:
            dependents[dep].append(node)

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        remaining = {node for node in nodes if indegree[node] > 0}
        # Every unplaced node has at least one unplaced dependency, so walking
        # along unplaced dependencies must eventually revisit a node.
        path = []
        position = {}
        current = min(remaining)
        while current not in position:
            position[current] = len(path)
            path.append(current)
            current = min(d for d in graph[current] if d in remaining)
        cycle = path[position[current]:] + [current]
        raise CycleError(cycle)

    return result
