def _unquote(value):
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        inner = value[1:-1]
        out = []
        i = 0
        while i < len(inner):
            ch = inner[i]
            if ch == '\\' and i + 1 < len(inner):
                out.append(inner[i + 1])
                i += 2
            else:
                out.append(ch)
                i += 1
        return ''.join(out)
    return value


def parse_kv(line):
    parts = []
    buf = []
    in_quote = False
    escaped = False

    for ch in line:
        if escaped:
            buf.append(ch)
            escaped = False
            continue
        if in_quote and ch == '\\':
            escaped = True
            buf.append(ch)
            continue
        if ch == '"':
            in_quote = not in_quote
            buf.append(ch)
        elif ch == ';' and not in_quote:
            parts.append(''.join(buf))
            buf = []
        else:
