import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__("dependency cycle: " + " -> ".join(cycle))


def _find_cycle(graph):
    """Return a cycle [p0, ..., pn] with p0 == pn, where each p_i depends on p_(i+1)."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}

    for start in sorted(graph):
        if color[start] != WHITE:
            continue
        path = [start]
        idx_stack = [0]
        color[start] = GRAY
        while path:
            node = path[-1]
            i = idx_stack[-1]
            nbrs = graph[node]
            if i < len(nbrs):
                idx_stack[-1] += 1
                nxt = nbrs[i]
                if color[nxt] == WHITE:
                    color[nxt] = GRAY
                    path.append(nxt)
                    idx_stack.append(0)
                elif color[nxt] == GRAY:
                    j = path.index(nxt)
                    return path[j:] + [nxt]
            else:
                color[node] = BLACK
                path.pop()
                idx_stack.pop()
    return None


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Every package, including those appearing only as dependencies.
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    # Deduplicated direct dependencies for each package.
    graph = {n: set(deps.get(n, [])) for n in nodes}

    # Reverse edges: for each package, which packages depend on it.
    dependents = {n: [] for n in nodes}
    for n, ds in graph.items():
        for d in ds:
            dependents[d].append(n)

    # Number of dependencies not yet placed.
    remaining = {n: len(ds) for n, ds in graph.items()}

    # Min-heap of packages whose dependencies are all placed.
    heap = [n for n in nodes if remaining[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for p in dependents[n]:
            remaining[p] -= 1
            if remaining[p] == 0:
                heapq.heappush(heap, p)

    if len(order) != len(nodes):
        cycle = _find_cycle({n: sorted(ds) for n, ds in graph.items()})
        raise CycleError(cycle)

    return order
