class Editor:
    """A one-line text buffer with a cursor and undo/redo."""

    def __init__(self) -> None:
        self._text = ""
        self._cursor = 0
        # Each entry is (before_state, after_state), where state = (text, cursor).
        self._undo_stack: list[tuple[tuple[str, int], tuple[str, int]]] = []
        self._redo_stack: list[tuple[tuple[str, int], tuple[str, int]]] = []

    @property
    def text(self) -> str:
        return self._text

    @property
    def cursor(self) -> int:
        return self._cursor

    def _record(self, before: tuple[str, int], after: tuple[str, int]) -> None:
        self._undo_stack.append((before, after))
        self._redo_stack.clear()

    def insert(self, s: str) -> None:
        before = (self._text, self._cursor)
        c = self._cursor
        self._text = self._text[:c] + s + self._text[c:]
        self._cursor = c + len(s)
        self._record(before, (self._text, self._cursor))

    def delete(self, n: int) -> None:
        c = self._cursor
        count = min(n, c) if n > 0 else 0
        if count <= 0:
            return
        before = (self._text, self._cursor)
        self._text = self._text[:c - count] + self._text[c:]
        self._cursor = c - count
        self._record(before, (self._text, self._cursor))

    def move(self, pos: int) -> None:
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        before, after = self._undo_stack.pop()
        self._text, self._cursor = before
        self._redo_stack.append((before, after))
        return True

    def redo(self) -> bool:
        if not self._redo_stack:
            return False
        before, after = self._redo_stack.pop()
        self._text, self._cursor = after
        self._undo_stack.append((before, after))
        return True
