import csv
import io


def column_stats(csv_text, column):
    reader = csv.reader(io.StringIO(csv_text))

    # Skip any leading blank lines before the header row.
    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = row
            break
    if header is None:
        raise KeyError(f"Column {column!r} not found in CSV header")

    # Normalize header names: drop a UTF-8 BOM and surrounding whitespace.
    names = [h.replace("\ufeff", "").strip() for h in header]
    target = column.strip()
    if target not in names:
        raise KeyError(f"Column {column!r} not found in CSV header")
    index = names.index(target)

    values = []
    for row in reader:
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        try:
            value = int(cell)
        except ValueError:
            value = float(cell)
        values.append(value)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
