import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version):
    if not isinstance(version, str):
        raise ValueError(f"invalid semantic version: {version!r}")
    m = _VERSION_RE.fullmatch(version)
    if m is None:
        raise ValueError(f"invalid semantic version: {version!r}")
    major, minor, patch, pre, _build = m.groups()
    core = (int(major), int(minor), int(patch))
    prerelease = None
    if pre is not None:
        ids = pre.split(".")
        for ident in ids:
            if len(ident) > 1 and ident[0] == "0" and ident.isdigit():
                raise ValueError(
                    f"leading zeros in numeric prerelease identifier: {version!r}"
                )
        prerelease = tuple(ids)
    return core, prerelease


def _cmp_identifier(x, y):
    x_num, y_num = x.isdigit(), y.isdigit()
    if x_num and y_num:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_num:
        return -1
    if y_num:
        return 1
    return (x > y) - (x < y)


def _cmp_prerelease(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    for x, y in zip(a, b):
        c = _cmp_identifier(x, y)
        if c:
            return c
    return (len(a) > len(b)) - (len(a) < len(b))


def compare_versions(a: str, b: str) -> int:
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)
    if core_a != core_b:
        return -1 if core_a < core_b else 1
    return _cmp_prerelease(pre_a, pre_b)


def sort_versions(versions: list[str]) -> list[str]:
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(compare_versions))
