        values.append(value)

    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0, "mean": None, "min": None, "max": None}

    total = sum(values)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
