import re
from functools import cmp_to_key

_CORE_NUMBER = re.compile(r"0|[1-9][0-9]*")
_IDENTIFIER = re.compile(r"[0-9A-Za-z-]+")
_NUMERIC = re.compile(r"[0-9]+")


def _parse(version):
    if not isinstance(version, str):
        raise ValueError(f"invalid version: {version!r}")

    # Build metadata follows the first '+' and is ignored for precedence.
    main, plus, build = version.partition("+")
    if plus:
        for ident in build.split("."):
            if not _IDENTIFIER.fullmatch(ident):
                raise ValueError(f"invalid build identifier in version: {version!r}")

    # Core and prerelease are separated by the first '-' (the core has none).
    core, dash, pre = main.partition("-")
    core_parts = core.split(".")
    if len(core_parts) != 3 or not all(_CORE_NUMBER.fullmatch(p) for p in core_parts):
        raise ValueError(f"invalid version: {version!r}")

    prerelease = None
    if dash:
        prerelease = pre.split(".")
        for ident in prerelease:
            if not _IDENTIFIER.fullmatch(ident):
                raise ValueError(f"invalid prerelease identifier in version: {version!r}")
            if _NUMERIC.fullmatch(ident) and len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"leading zero in numeric prerelease identifier: {version!r}")

    core_tuple = tuple(int(p) for p in core_parts)
    return core_tuple, prerelease


def _compare_identifiers(x, y):
    x_num = _NUMERIC.fullmatch(x) is not None
    y_num = _NUMERIC.fullmatch(y) is not None
    if x_num and y_num:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_num:
        return -1  # numeric identifiers are lower than alphanumeric ones
    if y_num:
        return 1
    return (x > y) - (x < y)  # ASCII lexical comparison


def compare_versions(a: str, b: str) -> int:
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)

    if core_a != core_b:
        return -1 if core_a < core_b else 1

    # A version with a prerelease has lower precedence than one without.
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for x, y in zip(pre_a, pre_b):
        result = _compare_identifiers(x, y)
        if result != 0:
            return result

    # All compared identifiers equal: more identifiers means higher precedence.
    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1


def sort_versions(versions: list[str]) -> list[str]:
    # Validate all entries up front so invalid input raises ValueError.
    for v in versions:
        _parse(v)
    # Python's sort is stable, so equal-precedence versions keep input order.
    return sorted(versions, key=cmp_to_key(compare_versions))
