import re

_NUM = r"(0|[1-9][0-9]*)"
_CORE_RE = re.compile(rf"{_NUM}\.{_NUM}\.{_NUM}")
_IDENT_RE = re.compile(r"[0-9A-Za-z-]+")
_NUMERIC_ID_RE = re.compile(r"[0-9]+")


def _parse_key(version: str):
    """Validate a SemVer 2.0.0 string and return a precedence key.

    Build metadata is validated but excluded from the key.
    """
    if not isinstance(version, str):
        raise ValueError(f"invalid version (not a string): {version!r}")

    main, plus, build = version.partition("+")
    if plus:
        if not build:
            raise ValueError(f"invalid version (empty build metadata): {version!r}")
        for ident in build.split("."):
            if not _IDENT_RE.fullmatch(ident):
                raise ValueError(f"invalid build identifier {ident!r} in {version!r}")

    core, dash, pre = main.partition("-")
    match = _CORE_RE.fullmatch(core)
    if not match:
        raise ValueError(f"invalid version core (need MAJOR.MINOR.PATCH): {version!r}")

    ids = []
    if dash:
        if not pre:
            raise ValueError(f"invalid version (empty prerelease): {version!r}")
        for ident in pre.split("."):
            if not _IDENT_RE.fullmatch(ident):
                raise ValueError(
                    f"invalid prerelease identifier {ident!r} in {version!r}"
                )
            if _NUMERIC_ID_RE.fullmatch(ident):
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError(
                        f"numeric prerelease identifier has leading zero: {version!r}"
                    )
                # Numeric identifiers sort below alphanumeric ones.
                ids.append((0, int(ident), ""))
            else:
                ids.append((1, 0, ident))

    major, minor, patch = (int(x) for x in match.groups()[0:1] + (
        _CORE_RE.fullmatch(core).group(2),
        _CORE_RE.fullmatch(core).group(3),
    ))

    # A version without prerelease has higher precedence than one with it.
    pre_key = (0, tuple(ids)) if ids else (1, ())
    return (major, minor, patch, pre_key)


def compare_versions(a: str, b: str) -> int:
    """Return -1 if a < b, 0 if equal precedence, 1 if a > b."""
    ka = _parse_key(a)
    kb = _parse_key(b)
    return (ka > kb) - (ka < kb)


def sort_versions(versions: list[str]) -> list[str]:
    """Sort versions in ascending precedence; stable for equal precedence."""
    return sorted(versions, key=_parse_key)
