import re

_NUMERIC_ID = r"0|[1-9][0-9]*"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_BUILD_ID = r"[0-9A-Za-z-]+"

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-(" + _PRE_ID + r"(?:\." + _PRE_ID + r")*))?"
    r"(?:\+(" + _BUILD_ID + r"(?:\." + _BUILD_ID + r")*))?"
)


def _parse(version: str):
    if not isinstance(version, str):
        raise ValueError(f"Invalid version: {version!r}")
    m = _VERSION_RE.fullmatch(version)
    if m is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, pre, _build = m.groups()
    return int(major), int(minor), int(patch), pre


def _precedence_key(version: str):
    major, minor, patch, pre = _parse(version)
    if pre is None:
        # A release (no prerelease) sorts above any prerelease with the same core.
        return (major, minor, patch, 1, ())
    ids = []
    for ident in pre.split("."):
        if ident.isdigit():
            # Numeric identifiers sort below alphanumeric ones; compare numerically.
            ids.append((0, int(ident), ""))
        else:
            # Alphanumeric identifiers compare lexically (ASCII).
            ids.append((1, 0, ident))
    # Tuple comparison gives: shorter prefix is lower, matching the spec.
    return (major, minor, patch, 0, tuple(ids))


def compare_versions(a: str, b: str) -> int:
    ka = _precedence_key(a)
    kb = _precedence_key(b)
    if ka < kb:
        return -1
    if ka > kb:
        return 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_precedence_key)
```

