import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r"([0-9]+)\.([0-9]+)\.([0-9]+)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version: str):
    """Validate a SemVer 2.0.0 string and return (major, minor, patch, prerelease_ids)."""
    m = _VERSION_RE.fullmatch(version)
    if m is None:
        raise ValueError(f"invalid semantic version: {version!r}")

    core = m.group(1), m.group(2), m.group(3)
    for part in core:
        if len(part) > 1 and part[0] == "0":
            raise ValueError(f"leading zero in version core: {version!r}")

    pre = m.group(4)
    pre_ids = None
    if pre is not None:
        pre_ids = pre.split(".")
        for ident in pre_ids:
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError(
                    f"leading zero in numeric prerelease identifier: {version!r}"
                )

    return int(core[0]), int(core[1]), int(core[2]), pre_ids


def _cmp_prerelease(pa, pb) -> int:
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1  # release is higher than any prerelease
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric is lower than alphanumeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(pa) != len(pb):
        return -1 if len(pa) < len(pb) else 1
    return 0


def compare_versions(a: str, b: str) -> int:
    """Return -1 if a < b, 0 if equal precedence, 1 if a > b."""
    maj_a, min_a, pat_a, pre_a = _parse(a)
    maj_b, min_b, pat_b, pre_b = _parse(b)

    for xa, xb in ((maj_a, maj_b), (min_a, min_b), (pat_a, pat_b)):
        if xa != xb:
            return -1 if xa < xb else 1

    return _cmp_prerelease(pre_a, pre_b)


def sort_versions(versions: list[str]) -> list[str]:
    """Return versions sorted by ascending precedence (stable; build metadata ignored)."""
    # Validate every entry up front so invalid input always raises ValueError.
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(compare_versions))
```

