import re
from functools import cmp_to_key

_NUMERIC_ID = r"0|[1-9][0-9]*"
_ALNUM_ID = r"[0-9]*[A-Za-z-][0-9A-Za-z-]*"
_PRE_ID = rf"(?:{_NUMERIC_ID}|{_ALNUM_ID})"

_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse(version: str):
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version: {version!r}")
    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, prerelease, _build = match.groups()
    core = (int(major), int(minor), int(patch))
    pre_ids = prerelease.split(".") if prerelease is not None else None
    return core, pre_ids


def _compare_identifiers(x: str, y: str) -> int:
    x_num = x.isdigit()
    y_num = y.isdigit()
    if x_num and y_num:
        xi, yi = int(x), int(y)
        return (xi > yi) - (xi < yi)
    if x_num:
        return -1
    if y_num:
        return 1
    return (x > y) - (x < y)


def compare_versions(a: str, b: str) -> int:
    a_core, a_pre = _parse(a)
    b_core, b_pre = _parse(b)

    if a_core != b_core:
        return -1 if a_core < b_core else 1

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        result = _compare_identifiers(x, y)
        if result != 0:
            return result

    if len(a_pre) == len(b_pre):
        return 0
    return -1 if len(a_pre) < len(b_pre) else 1


def sort_versions(versions: list[str]) -> list[str]:
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(compare_versions))
