            return 'UNKNOWN'
        price = self._prices[item]
        total = self.balance()
        if total < price:
            return 'INSUFFICIENT'
        # Coins inserted for this purchase are available as change.
        available = self._inventory + Counter(self._inserted)
        change = self._make_change(total - price, available)
        if change is None:
            return 'NO_CHANGE'
        self._inventory = available - Counter(change)
        self._inserted = []
        return change

    def cancel(self):
        returned = self._inserted
        self._inserted = []
        return returned

    def _make_change(self, amount, inventory):
        if amount == 0:
            return []
        if amount < 0 or amount % 5 != 0:
            return None
        inv25 = inventory[25]
        inv10 = inventory[10]
        inv5 = inventory[5]
        best = None
