    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_ROMAN_PATTERN = re.compile(
    r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"
)

_CHAR_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"expected an integer, got {n!r}")
    if not 1 <= n <= 3999:
        raise ValueError(f"value must be between 1 and 3999, got {n}")

    result = []
    for value, numeral in _ROMAN_VALUES:
        count, n = divmod(n, value)
        result.append(numeral * count)
    return "".join(result)


def from_roman(s):
    if not isinstance(s, str):
        raise ValueError(f"expected a string, got {s!r}")
    if not s:
        raise ValueError("empty string is not a valid Roman numeral")
    if any(ch not in _CHAR_VALUES for ch in s):
        raise ValueError(
            f"invalid characters in Roman numeral {s!r}; only uppercase I, V, X, L, C, D, M are allowed"
        )
    if not _ROMAN_PATTERN.fullmatch(s):
        raise ValueError(f"invalid Roman numeral {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _CHAR_VALUES[ch]
        if i + 1 < len(s) and value < _CHAR_VALUES[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999:
        raise ValueError(f"Roman numeral {s!r} is out of range")
    return total
