def parse_kv(line):
    """
    Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - Segments are separated by semicolons that are not inside double quotes.
    - 'key=value' maps key to value (a string).
    - A bare 'key' with no '=' maps to True.
    - A double-quoted value may contain semicolons and '=' characters.
    - An unterminated double quote is invalid input and raises ValueError.
    - Empty segments (e.g. from a trailing ';') are ignored.
    """
    # Split into segments on semicolons that are outside quoted regions.
    segments = []
    buf = []
    in_quotes = False
    for ch in line:
        if ch == '"':
            in_quotes = not in_quotes
            buf.append(ch)
        elif ch == ';' and not in_quotes:
            segments.append(''.join(buf))
            buf = []
        else:
            buf.append(ch)

    if in_quotes:
        raise ValueError(f"unterminated double quote in line: {line!r}")
    segments.append(''.join(buf))

    result = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue

        eq = segment.find('=')
        if eq == -1:
            # Bare key: must not contain quotes.
            if '"' in segment:
                raise ValueError(f"invalid bare key: {segment!r}")
            result[segment] = True
            continue

        key = segment[:eq].strip()
        if not key:
            raise ValueError(f"missing key in segment: {segment!r}")
        if '"' in key:
            raise ValueError(f"invalid key: {key!r}")

        value_raw = segment[eq + 1:].strip()
        if value_raw.startswith('"'):
            if len(value_raw) < 2 or not value_raw.endswith('"'):
                raise ValueError(f"malformed quoted value: {value_raw!r}")
            inner = value_raw[1:-1]
            if '"' in inner:
                raise ValueError(f"malformed quoted value: {value_raw!r}")
            value = inner
        else:
            if '"' in value_raw:
                raise ValueError(f"malformed value: {value_raw!r}")
            value = value_raw

        result[key] = value

    return result
```

