    buf = []
    in_quote = False

    for ch in line:
        if ch == '"':
            in_quote = not in_quote
            buf.append(ch)
        elif ch == ';' and not in_quote:
            segments.append(''.join(buf))
            buf = []
        else:
            buf.append(ch)

    if in_quote:
        raise ValueError(f"unterminated double quote in line: {line!r}")
    segments.append(''.join(buf))

    result = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
