        raise ValueError(f"unterminated quote in line: {line!r}")
    segments.append(''.join(buf))

    result = {}
    for segment in segments:
        segment = segment.strip()
        if not segment:
            continue

        if '=' not in segment:
            key = segment
            value = True
        else:
            key, _, raw = segment.partition('=')
            key = key.strip()
            raw = raw.strip()

            if raw.startswith('"'):
                closing = raw.find('"', 1)
                if closing == -1:
                    raise ValueError(f"unterminated quote for key {key!r}")
                if closing != len(raw) - 1:
                    raise ValueError(
                        f"unexpected characters after closing quote for key {key!r}"
                    )
                value = raw[1:closing]
            else:
                if '"' in raw:
                    raise ValueError(f"unexpected quote in value for key {key!r}")
                value = raw

        if not key:
            raise ValueError(f"empty key in segment {segment!r}")
        if '"' in key:
            raise ValueError(f"unexpected quote in key {key!r}")

        result[key] = value

    return result
