def _parse_quoted(raw):
    """Parse a double-quoted value starting at raw[0] == '"'.

    Returns (unescaped_value, remainder_after_closing_quote).
    Raises ValueError if the quote is never closed.
    """
    i = 1
    out = []
    n = len(raw)
    while i < n:
        c = raw[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("unterminated quoted value")
            out.append(raw[i + 1])
            i += 2
        elif c == '"':
            return ''.join(out), raw[i + 1:]
        else:
            out.append(c)
            i += 1
    raise ValueError("unterminated quoted value")


def parse_kv(line):
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - Entries are separated by semicolons that are not inside double quotes.
    - Bare keys (no '=') map to True.
    - Double-quoted values may contain semicolons; inside quotes a backslash
      escapes the following character (the backslash is dropped).
    - An unterminated quote raises ValueError.
    """
    # Pass 1: split on semicolons that lie outside quoted regions.
    tokens = []
    buf = []
    in_quote = False
    escaped = False
    for ch in line:
        if in_quote:
            buf.append(ch)
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '"':
                in_quote = False
        else:
            if ch == ';':
                tokens.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
                if ch == '"':
                    in_quote = True
    if in_quote:
        raise ValueError("unterminated quoted value")
    tokens.append(''.join(buf))

    # Pass 2: parse each entry into key/value.
    result = {}
    for tok in tokens:
        tok = tok.strip()
        if not tok:
            continue

        key, sep, raw = tok.partition('=')
        key = key.strip()
        if not key:
            raise ValueError("empty key in entry: %r" % tok)
        if '"' in key:
            raise ValueError("unexpected quote in key: %r" % key)

        if not sep:
            result[key] = True
            continue

        raw = raw.lstrip()
        if raw.startswith('"'):
            value, rest = _parse_quoted(raw)
            if rest.strip():
                raise ValueError("unexpected text after quoted value: %r" % rest.strip())
        else:
            if '"' in raw:
                raise ValueError("unexpected quote in value: %r" % raw)
            value = raw.strip()

        result[key] = value

    return result
