def parse_kv(line):
    result = {}
    n = len(line)
    pos = 0

    while pos < n:
        # Skip whitespace between items.
        while pos < n and line[pos].isspace():
            pos += 1
        if pos >= n:
            break

        # Skip empty items such as consecutive or trailing semicolons.
        if line[pos] == ';':
            pos += 1
            continue

        # Read the key up to '=', ';', or end of line.
        start = pos
        while pos < n and line[pos] not in '=;':
            pos += 1
        key = line[start:pos].strip()
        if not key:
            raise ValueError("empty key in config line")
        if '"' in key:
            raise ValueError(f"unexpected double quote in key {key!r}")

        # Bare key (no '=') maps to True.
        if pos >= n or line[pos] == ';':
            result[key] = True
            if pos < n:
                pos += 1  # consume ';'
            continue

        # Key with '=': consume '=' and any leading whitespace of the value.
        pos += 1
        while pos < n and line[pos].isspace():
            pos += 1

        if pos < n and line[pos] == '"':
            # Quoted value: may contain ';', and backslash escapes the next char.
            pos += 1
            buf = []
            closed = False
            while pos < n:
                c = line[pos]
                if c == '\\':
                    if pos + 1 >= n:
                        break  # backslash at end of line: quote is unterminated
                    buf.append(line[pos + 1])
                    pos += 2
                elif c == '"':
                    closed = True
                    pos += 1
                    break
                else:
                    buf.append(c)
                    pos += 1

            if not closed:
                raise ValueError(f"unterminated double quote in value for key {key!r}")

            value = ''.join(buf)

            # Only whitespace may follow the closing quote before ';' or end.
            while pos < n and line[pos].isspace():
                pos += 1
            if pos < n and line[pos] != ';':
                raise ValueError(f"unexpected characters after quoted value for key {key!r}")
            if pos < n:
                pos += 1  # consume ';'
        else:
            # Unquoted value runs until ';' or end of line.
            start = pos
            while pos < n and line[pos] != ';':
                pos += 1
            value = line[start:pos].strip()
            if '"' in value:
                raise ValueError(f"unexpected double quote in unquoted value for key {key!r}")
            if pos < n:
                pos += 1  # consume ';'

        result[key] = value

    return result
