import csv
import io


def column_stats(csv_text, column):
    """Return count, sum, mean, min and max for a numeric CSV column.

    Blank lines (before or after the header) are skipped, and empty cells in
    the target column are ignored. Raises ValueError if the column is missing
    from the header or a non-empty cell is not numeric.
    """
    reader = csv.reader(io.StringIO(csv_text))

    header = None
    for row in reader:
        if any(cell.strip() for cell in row):
            header = [cell.strip() for cell in row]
            break

    if header is None:
        raise ValueError(f"column not found: {column!r}")
    if column not in header:
        raise ValueError(f"column not found: {column!r}")

    index = header.index(column)

    values = []
    for row in reader:
        if not any(cell.strip() for cell in row):
            continue
        if index >= len(row):
            continue
        cell = row[index].strip()
        if cell == "":
            continue
        try:
            number = float(cell)
        except ValueError:
            raise ValueError(
                f"non-numeric value in column {column!r}: {cell!r}"
            ) from None
        values.append(number)

    count = len(values)
    total = sum(values)
    if count == 0:
        return {
            "count": 0,
            "sum": 0.0,
            "mean": None,
            "min": None,
            "max": None,
        }

    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
