class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)

    def __init__(self, prices, coins):
        self._prices = dict(prices)
        self._inventory = {int(denom): int(count) for denom, count in dict(coins).items()}
        self._inserted = []
        self._balance = 0

    def insert(self, coin):
        if coin not in self.ACCEPTED_COINS:
            return False
        self._inserted.append(coin)
        self._balance += coin
        return True

    def balance(self):
        return self._balance

    def select(self, item):
        if item not in self._prices:
            return 'UNKNOWN'

        price = self._prices[item]
        if self._balance < price:
            return 'INSUFFICIENT'

        change_due = self._balance - price

        # Inserted coins join the inventory before change is computed.
        trial_inventory = dict(self._inventory)
        for coin in self._inserted:
            trial_inventory[coin] = trial_inventory.get(coin, 0) + 1

        change = self._make_change(change_due, trial_inventory)
        if change is None:
            # Transaction stays open; inventory is left unchanged.
            return 'NO_CHANGE'

        # Commit: inserted coins stay in the machine, change leaves it.
        for coin in change:
            trial_inventory[coin] -= 1
        self._inventory = {d: c for d, c in trial_inventory.items() if c > 0}
        self._inserted = []
        self._balance = 0
        return change

    def cancel(self):
        returned = list(self._inserted)
        self._inserted = []
        self._balance = 0
        return returned

    @staticmethod
    def _make_change(amount, inventory):
        """Return the fewest coins from inventory summing to amount, or None."""
        if amount == 0:
            return []

        # Expand each denomination into at most `amount // denom` copies.
        copies = []
        for denom in sorted(inventory, reverse=True):
            count = inventory[denom]
            if denom <= 0 or count <= 0 or denom > amount:
                continue
            copies.extend([denom] * min(count, amount // denom))

        INF = float('inf')
        dp = [INF] * (amount + 1)
        dp[0] = 0
        took = [[False] * (amount + 1) for _ in range(len(copies))]

        # 0/1 knapsack over individual coin copies (bounded inventory).
        for i, denom in enumerate(copies):
            for a in range(amount, denom - 1, -1):
                if dp[a - denom] + 1 < dp[a]:
                    dp[a] = dp[a - denom] + 1
                    took[i][a] = True

        if dp[amount] == INF:
            return None

        result = []
        a = amount
        for i in range(len(copies) - 1, -1, -1):
            if took[i][a]:
                result.append(copies[i])
                a -= copies[i]
        return result
