from typing import Any, Callable, Optional, Tuple

Result = Optional[Tuple[Any, int]]
Parser = Callable[[str, int], Result]


class ParseError(Exception):
    """Raised when parsing fails. `pos` is the input index where the error occurred."""

    def __init__(self, message: str, pos: int):
        super().__init__(message)
        self.pos = pos


def satisfy(pred: Callable[[str], bool]) -> Parser:
    """Match a single character for which `pred` returns True."""
    def p(s: str, i: int) -> Result:
        if i < len(s) and pred(s[i]):
            return s[i], i + 1
        return None
    return p


def char(c: str) -> Parser:
    """Match exactly the single character `c`."""
    if len(c) != 1:
        raise ValueError("char() expects a single character")
    return satisfy(lambda ch: ch == c)


def string(t: str) -> Parser:
    """Match the literal string `t`."""
    def p(s: str, i: int) -> Result:
        if s.startswith(t, i):
            return t, i + len(t)
        return None
    return p


def seq(*parsers: Parser) -> Parser:
    """Run parsers in order; succeed with a list of their values."""
    def p(s: str, i: int) -> Result:
        values = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return values, i
    return p


def alt(*parsers: Parser) -> Parser:
    """Return the result of the first parser that succeeds."""
    def p(s: str, i: int) -> Result:
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(parser: Parser) -> Parser:
    """
    Apply `parser` zero or more times, returning a list of values.

    If `parser` succeeds without consuming input, `many` stops and returns the
    values collected so far (the non-consuming match is not included). This
    avoids infinite loops and does not raise ValueError.
    """
    def p(s: str, i: int) -> Result:
        values = []
        while True:
            r = parser(s, i)
            if r is None:
                break
            v, j = r
            if j == i:
                break
            values.append(v)
            i = j
        return values, i
    return p


def sep_by(parser: Parser, sep: Parser) -> Parser:
    """Zero or more `parser` items separated by `sep`; returns a list of values."""
    def p(s: str, i: int) -> Result:
        first = parser(s, i)
        if first is None:
            return [], i
        v, i = first
        values = [v]
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            _, j = sr
            pr = parser(s, j)
            if pr is None:
                break
            v, k = pr
            if k == i:
                break
            values.append(v)
            i = k
        return values, i
    return p


def map_(f: Callable[[Any], Any], parser: Parser) -> Parser:
    """Transform the value produced by `parser` with `f`."""
    def p(s: str, i: int) -> Result:
        r = parser(s, i)
        if r is None:
            return None
        v, j = r
        return f(v), j
    return p


def parse(parser: Parser, s: str) -> Any:
    """
    Parse the entire string `s` with `parser`.

    Raises ParseError if the parser fails or does not consume all of the input.
    """
    r = parser(s, 0)
    if r is None:
        raise ParseError("no match at position 0", 0)
    v, j = r
    if j != len(s):
        raise ParseError(f"unexpected input at position {j}", j)
    return v
