from typing import Any, Callable, Optional, Tuple

Parser = Callable[[str, int], Optional[Tuple[Any, int]]]


class ParseError(Exception):
    def __init__(self, message: str, pos: int):
        super().__init__(f"{message} at position {pos}")
        self.message = message
        self.pos = pos


def satisfy(pred: Callable[[str], bool]) -> Parser:
    def p(s: str, i: int):
        if i < len(s) and pred(s[i]):
            return s[i], i + 1
        return None
    return p


def char(c: str) -> Parser:
    if len(c) != 1:
        raise ValueError("char() expects a single character")
    return satisfy(lambda x: x == c)


def string(text: str) -> Parser:
    n = len(text)

    def p(s: str, i: int):
        if s.startswith(text, i):
            return text, i + n
        return None
    return p


def seq(*parsers: Parser) -> Parser:
    """Run parsers in order. Returns a tuple of their values."""
    def p(s: str, i: int):
        values = []
        for q in parsers:
            r = q(s, i)
            if r is None:
                return None
            v, i = r
            values.append(v)
        return tuple(values), i
    return p


def alt(*parsers: Parser) -> Parser:
    """Return the result of the first parser that succeeds."""
    def p(s: str, i: int):
        for q in parsers:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(parser: Parser) -> Parser:
    """
    Zero or more repetitions, returning a list of values.
    If the parser succeeds without consuming input, many() stops and
    returns the values collected so far (that non-consuming match is
    not included).
    """
    def p(s: str, i: int):
        values = []
        while True:
            r = parser(s, i)
            if r is None:
                break
            v, j = r
            if j == i:
                break
            values.append(v)
            i = j
        return values, i
    return p


def sep_by(parser: Parser, sep: Parser) -> Parser:
    """
    Zero or more occurrences of `parser` separated by `sep`, returning a list.
    A separator not followed by a valid item is not consumed.
    """
    def p(s: str, i: int):
        first = parser(s, i)
        if first is None:
            return [], i
        v, i = first
        values = [v]
        while True:
            sr = sep(s, i)
            if sr is None:
                break
            _, j = sr
            r = parser(s, j)
            if r is None:
                break
            v, i = r
            values.append(v)
        return values, i
    return p


def map_(f: Callable[..., Any], parser: Parser) -> Parser:
    """
    Apply f to the parser's value. If the value is a tuple (e.g. from seq),
    it is unpacked: f(*value). Otherwise f(value) is called with a single argument.
    """
    def p(s: str, i: int):
        r = parser(s, i)
        if r is None:
            return None
        v, j = r
        if isinstance(v, tuple):
            return f(*v), j
        return f(v), j
    return p


def parse(parser: Parser, s: str) -> Any:
    """Parse the entire input string; raises ParseError on failure."""
    r = parser(s, 0)
    if r is None:
        raise ParseError("no match", 0)
    v, i = r
    if i != len(s):
        raise ParseError("unexpected input", i)
    return v
