import re


def wrap_text(text, width):
    """Greedily word-wrap text to the given width.

    Paragraphs are separated by blank lines and remain separate in the output.
    A word longer than width is hard-broken into chunks of at most width
    characters. The leftover piece is then wrapped like any other word, so it
    can share a line with the words that follow.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    paragraphs = re.split(r"\n\s*\n", text.strip())
    wrapped_paragraphs = []

    for paragraph in paragraphs:
        words = paragraph.split()
        if not words:
            continue

        lines = []
        current = ""

        for word in words:
            # Hard-break words longer than the width into full-width chunks.
            while len(word) > width:
                if current:
                    lines.append(current)
                    current = ""
                lines.append(word[:width])
                word = word[width:]

            # The (possibly shortened) word is now at most width characters.
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word

        if current:
            lines.append(current)

