def hole_smallest_palindromic_suffix_start(s: str) -> int:
    """Return the smallest index i in range(len(s) + 1) such that s[i:] is a palindrome.

    The empty suffix (i == len(s)) counts as a palindrome, so a valid index is
    always returned. For s == "" the result is 0.
    """
    for i in range(len(s) + 1):
        suffix = s[i:]
        if suffix == suffix[::-1]:
            return i
    return len(s)
