    first = stem[0]
    return ('a' <= first <= 'z') or ('A' <= first <= 'Z')

def hole_extension_is_allowed(ext: str) -> bool:
    """Return True if `ext` is exactly one of 'txt', 'exe', or 'dll' (case-sensitive,
    no leading dot). Return False for any other string, including the empty string.
    """
