from typing import List


def hole_apply_operator(op: str, left: int, right: int) -> int:
    """Return the result of applying binary operator `op` to `left` and `right`.

    `op` is one of '+', '-', '*', '//', '**'. Use the usual Python semantics:
    '//' is floor division and '**' is exponentiation. Division by zero must
    raise ZeroDivisionError. Must not call eval or exec.
    """
    if op == '+':
        return left + right
    if op == '-':
        return left - right
    if op == '*':
        return left * right
    if op == '//':
        return left // right
    if op == '**':
        return left ** right
    raise ValueError(f'unsupported operator: {op!r}')


def hole_evaluate_with_precedence(operators: List[str], operands: List[int]) -> int:
    """Return the value of operands[0] op[0] operands[1] op[1] ... operands[-1].

    Precedence is normal arithmetic: '**' binds tightest, then '*' and '//',
    then '+' and '-'. Operators of equal precedence associate left-to-right,
    except '**', which associates right-to-left. Compute every step by calling
    hole_apply_operator. Inputs are already validated: len(operands) ==
    len(operators) + 1 and every operator is in ALLOWED_OPERATORS.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '//': 2, '**': 3}
    right_assoc = {'**'}

    values: List[int] = [operands[0]]
    pending: List[str] = []

    def reduce_top() -> None:
        op = pending.pop()
        right = values.pop()
        left = values.pop()
        values.append(hole_apply_operator(op, left, right))

    for op, nxt in zip(operators, operands[1:]):
        while pending:
            top = pending[-1]
            if precedence[top] > precedence[op] or (
                precedence[top] == precedence[op] and op not in right_assoc
            ):
                reduce_top()
            else:
                break
        pending.append(op)
        values.append(nxt)

    while pending:
        reduce_top()

    return values[0]
