import sys

def hole_first_index(s: str, ch: str) -> int:
    """Return the smallest index i such that s[i] == ch.

    Returns -1 if ch does not occur in s. Assumes ch is a single character.
    """
    for i, c in enumerate(s):
        if c == ch:
            return i
    return -1

def hole_last_index(s: str, ch: str) -> int:
    """Return the largest index i such that s[i] == ch.

    Returns -1 if ch does not occur in s. Assumes ch is a single character.
    """
    for i in range(len(s) - 1, -1, -1):
        if s[i] == ch:
            return i
    return -1
