import re

def hole_national_digits(digits: str, has_plus: bool) -> str:
    if not digits:
        raise ValueError('empty phone number')
    if len(digits) == 11:
        if digits[0] != '1':
            raise ValueError('unsupported country code')
        return digits[1:]
    if len(digits) == 10:
        if has_plus:
            raise ValueError('a leading + requires country code 1')
        return digits
    raise ValueError(f'expected 10 or 11 digits, got {len(digits)}')

def hole_is_valid_nanp(national: str) -> bool:
    if len(national) != 10 or not national.isdigit():
        return False
    area, exchange = national[:3], national[3:6]
    # NPA and NXX must start with 2-9
    if area[0] not in '23456789' or exchange[0] not in '23456789':
        return False
    # N11 codes are reserved for service codes
    if area[1:] == '11' or exchange[1:] == '11':
        return False
    return True
