def hole_split_fields(line: str) -> list[str]:
    fields: list[str] = []
    buf: list[str] = []
    in_quote = False
    i = 0
    n = len(line)

    def flush() -> None:
        field = ''.join(buf).strip()
        if field:
            fields.append(field)
        buf.clear()

    while i < n:
        ch = line[i]
        if in_quote and ch == '\\' and i + 1 < n:
            # Inside quotes, a backslash escapes the next character.
            buf.append(ch)
            buf.append(line[i + 1])
            i += 2
            continue
        if ch == '"':
            in_quote = not in_quote
            buf.append(ch)
        elif ch == ';' and not in_quote:
            flush()
        else:
            buf.append(ch)
        i += 1

    flush()
    return fields


def hole_parse_field(field: str) -> tuple[str, object]:
    def unquote(text: str) -> str:
        # text must begin with a double quote; must end with an unescaped one.
        out: list[str] = []
        i = 1
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == '\\' and i + 1 < n and text[i + 1] in ('"', '\\'):
                out.append(text[i + 1])
                i += 2
                continue
            if ch == '"':
                if i != n - 1:
                    raise ValueError(f'unexpected text after closing quote: {text!r}')
                return ''.join(out)
            out.append(ch)
            i += 1
        raise ValueError(f'unterminated quoted value: {text!r}')

    if '=' in field:
        raw_key, raw_value = field.split('=', 1)
        key = raw_key.strip()
        if not key or '"' in key:
            raise ValueError(f'empty or invalid key in field: {field!r}')
        value_text = raw_value.strip()
        if value_text.startswith('"'):
            value: object = unquote(value_text)
        else:
            value = value_text
        return (key, value)

    key = field.strip()
    if not key or '"' in key:
        raise ValueError(f'empty or invalid key in field: {field!r}')
    return (key, True)
