from typing import List, Tuple


def hole_binding_power(op: str) -> Tuple[int, bool]:
    """
    Return (precedence, right_assoc) for a binary operator.

    op is one of '+', '-', '*', '/', '%', '^'.
    Higher precedence integers bind more tightly.
    '+' and '-' must share the lowest precedence; '*', '/', '%' must share a
    higher one; '^' must have the highest of the binary operators.
    right_assoc must be True only for '^' (so 2^3^2 == 2^9).
    """
    if op in ('+', '-'):
        return (1, False)
    if op in ('*', '/', '%'):
        return (2, False)
    if op == '^':
        return (3, True)
    raise SyntaxError(f'unknown operator {op!r}')


def hole_apply_binary(op: str, lhs: int, rhs: int) -> int:
    """
    Apply a binary operator to two integers and return an int.

    '+', '-', '*': ordinary exact integer arithmetic.
    '/': C-style integer division, truncating toward zero (-7/2 == -3).
         Raise ZeroDivisionError if rhs == 0.
    '%': C-style remainder, so that lhs == hole-division(lhs, rhs) * rhs + result
         and the result has the sign of lhs (-7%3 == -1). Raise
         ZeroDivisionError if rhs == 0.
    '^': lhs raised to rhs. Raise ValueError if rhs < 0.
    """
    if op == '+':
        return lhs + rhs
    if op == '-':
        return lhs - rhs
    if op == '*':
        return lhs * rhs
    if op == '/':
        if rhs == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(lhs) // abs(rhs)
        return q if (lhs < 0) == (rhs < 0) else -q
    if op == '%':
        if rhs == 0:
            raise ZeroDivisionError('modulo by zero')
        r = abs(lhs) % abs(rhs)
        return r if lhs >= 0 else -r
    if op == '^':
        if rhs < 0:
            raise ValueError('negative exponent is not supported for integers')
        return lhs ** rhs
    raise SyntaxError(f'unknown operator {op!r}')


def hole_parse_expression(tokens: List[Token]) -> int:
    """
    Parse the token list as a complete arithmetic expression and return its value.

    Grammar to accept: binary + - * / % ^, unary minus, and parentheses.
    Use hole_binding_power for operator precedence/associativity and
    hole_apply_binary to compute each operation.
    Decide and document how unary minus interacts with '^' (e.g. -2^2).
    Raise SyntaxError for malformed input: empty input, unbalanced
    parentheses, missing operands, dangling operators, or trailing tokens.
    Must consume every token; leftover tokens are a SyntaxError.

    Design decision: unary minus binds more loosely than '^', so -2^2 == -(2^2) == -4,
    matching standard mathematical convention. Its operand is parsed at the
    precedence level of '^', so -2*3 == (-2)*3 and 2^-3 is accepted as 2^(-3).
    """
    if not tokens:
        raise SyntaxError('empty expression')

    pos = 0
    n = len(tokens)
    unary_operand_min = hole_binding_power('^')[0]

    def parse_expr(min_prec: int) -> int:
        nonlocal pos
        lhs = parse_unary()
        while pos < n and tokens[pos].kind == 'op':
            op = tokens[pos].value
            prec, right_assoc = hole_binding_power(op)
            if prec < min_prec:
                break
            pos += 1
            next_min = prec if right_assoc else prec + 1
            rhs = parse_expr(next_min)
            lhs = hole_apply_binary(op, lhs, rhs)
        return lhs

    def parse_unary() -> int:
        nonlocal pos
        if pos < n and tokens[pos].kind == 'op' and tokens[pos].value == '-':
            pos += 1
            return -parse_expr(unary_operand_min)
        return parse_primary()

    def parse_primary() -> int:
        nonlocal pos
        if pos >= n:
            raise SyntaxError('unexpected end of expression')
        tok = tokens[pos]
        if tok.kind == 'num':
            pos += 1
            return int(tok.value)
        if tok.kind == 'lp':
            pos += 1
            value = parse_expr(1)
            if pos >= n or tokens[pos].kind != 'rp':
                raise SyntaxError('unbalanced parentheses: missing ")"')
            pos += 1
            return value
        if tok.kind == 'rp':
            raise SyntaxError(f'unbalanced parentheses: unexpected ")" at token {pos}')
        raise SyntaxError(f'missing operand before {tok.value!r}')

    result = parse_expr(1)
    if pos != n:
        leftover = tokens[pos]
        if leftover.kind == 'rp':
            raise SyntaxError('unbalanced parentheses: unexpected ")"')
        raise SyntaxError(f'trailing token {leftover.value!r}')
    return result
