def hole_accept_step(start: int, end: int) -> bool:
    """Decide whether a repetition step is accepted by many().

    Called with the index where the step started and the index where the
    element parser reported it ended. Return True iff the step should be
    appended and the loop should continue, False otherwise (the loop then
    stops and the step is discarded).

    Must return False whenever end == start, or many() may loop forever.
    """
    raise NotImplementedError


def hole_error_pos(s: str, consumed: int) -> int:
    """Choose the position reported in a ParseError raised by parse().

    `consumed` is the index reached by the top-level parser when it succeeded
    (the position of the unconsumed leftover), or 0 when it returned None.
    Return an int in the closed range [0, len(s)].
    """
    raise NotImplementedError


def hole_sep_step(item: Parser, sep: Parser, s: str, i: int) -> Result:
    """Attempt one repetition of `sep` followed by `item`, starting at index i.

    On success, return (value_of_item, new_index) where new_index is the index
    after the item. On failure, return None; the caller then keeps its position
    at i, so any input consumed by a partially matched separator is given back
    (backtracking).

    Must return None unless new_index > i, so that sep_by() terminates.
    """
    raise NotImplementedError


# ---------------------------------------------------------------------------
# Public API.
# ---------------------------------------------------------------------------

def char(c: str) -> Parser:
    """Parser matching exactly the single character `c`, returning it."""
    if len(c) != 1:
        raise ValueError("char() expects a single character")

    def p(s: str, i: int) -> Result:
        if i < len(s) and s[i] == c:
            return (c, i + 1)
        return None

    return p


def string(t: str) -> Parser:
    """Parser matching the literal string `t`, returning it."""

    def p(s: str, i: int) -> Result:
        if s.startswith(t, i):
            return (t, i + len(t))
        return None

    return p


def satisfy(pred: Callable[[str], bool]) -> Parser:
    """Parser matching one character for which `pred` is true, returning it."""

    def p(s: str, i: int) -> Result:
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return None

    return p


def seq(*ps: Parser) -> Parser:
    """Run parsers in order; return a list of their values, or None if any fails."""

    def p(s: str, i: int) -> Result:
        values: List[Any] = []
        cur = i
        for q in ps:
            r = q(s, cur)
            if r is None:
                return None
            v, cur = r
            values.append(v)
        return (values, cur)

    return p


def alt(*ps: Parser) -> Parser:
    """Return the first successful result of the parsers, tried in order."""

    def p(s: str, i: int) -> Result:
        for q in ps:
            r = q(s, i)
            if r is not None:
                return r
        return None

    return p


def many(q: Parser) -> Parser:
    """Apply `q` repeatedly (zero or more times); return a list of values."""

    def p(s: str, i: int) -> Result:
        values: List[Any] = []
        cur = i
        while True:
            r = q(s, cur)
            if r is None or not hole_accept_step(cur, r[1]):
                break
            v, new_i = r
            values.append(v)
            cur = new_i
        return (values, cur)

