        if first is None:
            return ([], i)
        values: List[Any] = [first[0]]
        cur = first[1]
        while True:
            r = hole_sep_step(item, sep, s, cur)
            if r is None:
                break
            v, cur = r
            values.append(v)
        return (values, cur)

    return p


def map_(q: Parser, f: Callable[[Any], Any]) -> Parser:
    """Apply `f` to the value produced by `q`, leaving the position unchanged."""

    def p(s: str, i: int) -> Result:
        r = q(s, i)
        if r is None:
            return None
        v, new_i = r
        return (f(v), new_i)

    return p


def parse(q: Parser, s: str) -> Any:
    """Parse all of `s` with `q` and return the value.

    Raises ParseError if `q` fails or does not consume the entire input.
    """
    r = q(s, 0)
    if r is None:
        raise ParseError("no match", hole_error_pos(s, 0))
    value, end = r
    if end != len(s):
        raise ParseError("unconsumed input", hole_error_pos(s, end))
    return value


