import bisect
from typing import List, Tuple
Interval = Tuple[int, int]

def hole_overlaps(bookings: List[Interval], start: int, end: int) -> bool:
    i = bisect.bisect_left(bookings, (start,))
    if i < len(bookings) and bookings[i][0] < end:
        return True
    if i > 0 and bookings[i - 1][1] > start:
        return True
    return False

def hole_find_booking(bookings: List[Interval], start: int, end: int) -> int:
    i = bisect.bisect_left(bookings, (start, end))
    if i < len(bookings) and bookings[i] == (start, end):
        return i
    return -1

def hole_free_gaps(bookings: List[Interval], lo: int, hi: int, min_len: int) -> List[Interval]:
    result: List[Interval] = []
    cur = lo
    for a, b in bookings:
        if b <= cur:
            continue
        if a >= hi:
            break
        if a > cur and a - cur >= min_len:
            result.append((cur, a))
        cur = max(cur, b)
        if cur >= hi:
            break
    if cur < hi and hi - cur >= min_len:
        result.append((cur, hi))
    return result
