    """Run `p` from position 0 and require it to consume the entire input.
    Returns the parsed value. Raises ParseError on failure.
    """
    r = p(s, 0)
    if r is None:
        raise ParseError("no match", hole_failure_position(s))
    value, end = r
    if end != len(s):
