    """Zero or more `q` separated by `sep`. Value is the list of `q` values.
    A separator not followed by a successful `q` is not consumed.
    """

    def p(s: str, i: int) -> Result:
        r = q(s, i)
        if r is None:
            return ([], i)
        v, pos = r
        values: List[Any] = [v]
        while True:
            r_sep = sep(s, pos)
            if r_sep is None:
                break
            r_item = q(s, r_sep[1])
            if r_item is None:
                break
            v, pos = r_item
            values.append(v)
        return (values, pos)
