def hole_compare_identifiers(x: str, y: str) -> int:
    digits = '0123456789'
    x_num = all(c in digits for c in x)
    y_num = all(c in digits for c in y)
    if x_num and y_num:
        nx, ny = int(x), int(y)
        return (nx > ny) - (nx < ny)
    if x_num != y_num:
        return -1 if x_num else 1
