import re

_SEMVER_RE = re.compile(
    r'([0-9]+)\.([0-9]+)\.([0-9]+)'
    r'(?:-([0-9A-Za-z.-]+))?'
    r'(?:\+([0-9A-Za-z.-]+))?'
)
_IDENT_RE = re.compile(r'[0-9A-Za-z-]+')
_NUMERIC_RE = re.compile(r'[0-9]+')


def hole_parse_version(version: str) -> tuple[tuple[int, int, int], tuple[str, ...]]:
    """Validate a Semantic Versioning 2.0.0 string and split out its precedence data.

    Must raise ValueError if `version` is not a str or does not match the SemVer 2.0.0
    grammar. Rules to enforce:
      - Core is MAJOR.MINOR.PATCH with non-negative decimal integers.
      - Numeric core identifiers must not have leading zeros (except "0" itself).
      - An optional prerelease starts with "-" and is dot-separated identifiers of
        [0-9A-Za-z-]; numeric prerelease identifiers must not have leading zeros.
      - An optional build metadata part starts with "+" and is dot-separated
        identifiers of [0-9A-Za-z-] (leading zeros allowed). It is validated here
        but must not affect precedence.

    Returns a 2-tuple:
      - core: (major, minor, patch) as ints.
      - prerelease: tuple of prerelease identifier strings, in order; () if none.
    """
    if not isinstance(version, str):
        raise ValueError(f'version must be a str, got {type(version).__name__}')

    match = _SEMVER_RE.fullmatch(version)
    if match is None:
        raise ValueError(f'invalid semantic version: {version!r}')

    major_s, minor_s, patch_s, pre_s, build_s = match.groups()

    for num in (major_s, minor_s, patch_s):
        if len(num) > 1 and num[0] == '0':
            raise ValueError(f'leading zero in core version: {version!r}')

    if pre_s is not None:
        prerelease = tuple(pre_s.split('.'))
        for ident in prerelease:
            if not _IDENT_RE.fullmatch(ident):
                raise ValueError(f'invalid prerelease identifier in: {version!r}')
            if _NUMERIC_RE.fullmatch(ident) and len(ident) > 1 and ident[0] == '0':
                raise ValueError(f'leading zero in numeric prerelease identifier: {version!r}')
    else:
        prerelease = ()

    if build_s is not None:
        for ident in build_s.split('.'):
            if not _IDENT_RE.fullmatch(ident):
                raise ValueError(f'invalid build metadata identifier in: {version!r}')

    return (int(major_s), int(minor_s), int(patch_s)), prerelease


def hole_compare_prerelease(pre_a: tuple[str, ...], pre_b: tuple[str, ...]) -> int:
    """Compare two prerelease identifier tuples with equal core versions.

    Must return -1 if pre_a has lower precedence than pre_b, 0 if equal, and 1 if
    higher. Rules:
      - An empty tuple (no prerelease) has higher precedence than any non-empty tuple.
      - Identifiers are compared left to right:
          * both numeric: compare as integers;
          * numeric vs alphanumeric: numeric is lower;
          * both alphanumeric: compare in ASCII lexical order.
      - If all shared identifiers are equal, the shorter tuple has lower precedence.
    """
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for x, y in zip(pre_a, pre_b):
        x_numeric = _NUMERIC_RE.fullmatch(x) is not None
        y_numeric = _NUMERIC_RE.fullmatch(y) is not None
        if x_numeric and y_numeric:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_numeric:
            return -1
        elif y_numeric:
            return 1
        elif x != y:
            return -1 if x < y else 1

    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1
