def hole_palindromic_suffix_start(s: str) -> int:
    """Return the smallest index k in [0, len(s)] such that s[k:] is a palindrome."""
    for k in range(len(s) + 1):
        suffix = s[k:]
        if suffix == suffix[::-1]:
            return k
    return len(s)


def hole_completion(s: str, k: int) -> str:
    """Return the string to append to s so that s + result is a palindrome."""
    return s[:k][::-1]
