from typing import Dict, Union

def hole_check_scan_end(line: str, in_quotes: bool, escape: bool) -> None:
    if in_quotes:
        raise ValueError("unterminated quoted value")
    # The scanner only sets escape inside quotes, so it is already covered
    # by in_quotes. Outside quotes a backslash is a literal character, so a
    # trailing backslash there is well formed and needs no handling.
    return None

def hole_split_pair(segment: str) -> tuple:
    if '=' not in segment:
        key = segment.strip()
        if not key:
            raise ValueError("empty key")
        return (key, True)

    raw_key, raw_value = segment.split('=', 1)
    key = raw_key.strip()
    if not key:
        raise ValueError("empty key")

    value = raw_value.strip()
    if value.startswith('"'):
        # Find the closing unescaped quote; it must be the last character.
        i = 1
        close = -1
        while i < len(value):
            ch = value[i]
            if ch == '\\':
                i += 2
                continue
            if ch == '"':
                close = i
                break
            i += 1
        if close == -1:
            raise ValueError("unterminated quoted value")
        if close != len(value) - 1:
            raise ValueError("unexpected text after closing quote")
        return (key, _unquote(value[1:close]))

    if '"' in value:
        raise ValueError("quote character in unquoted value")
    return (key, value)

def _unquote(text: str) -> str:
    out = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '\\' and i + 1 < len(text):
            out.append(text[i + 1])
            i += 2
        else:
            out.append(ch)
            i += 1
    return ''.join(out)
