from __future__ import annotations


def hole_split_fields(line: str) -> list[str]:
    """Split `line` into raw fields on ';' characters that are outside double quotes.

    Return a list of raw, unstripped field strings, including empty ones.
    A backslash inside quotes escapes the following character for quote-tracking
    purposes, and both characters must remain in the returned field text unchanged.
    Raise ValueError if the line ends while still inside an open quote.
    """
    raise NotImplementedError


def hole_split_key_value(field: str) -> tuple[str, str | None]:
    """Split a stripped, non-empty field into (key, raw_value).

    Return (key, None) when the field contains no '=' outside double quotes
    (a bare key such as 'debug').
    Otherwise return (key, raw_value), where raw_value is the text after the first
    unquoted '='. Both key and raw_value must be stripped of surrounding whitespace.
    raw_value may be the empty string. The returned raw_value is not unquoted yet.
    """
    raise NotImplementedError


def hole_unquote(raw: str) -> str:
    """Convert a stripped raw value into its final string value.

    If `raw` is wrapped in a matching pair of double quotes, return the inner text
    with backslash escapes resolved, so a backslash followed by any character yields
    that character. Otherwise return `raw` unchanged.
    """
    raise NotImplementedError


def parse_kv(line: str) -> dict[str, str | bool]:
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    Fields are separated by unquoted semicolons. Empty fields are ignored.
    Bare keys map to True. Keyed fields map to their unquoted string value.
    Raises ValueError on an unterminated quote.
    """
    result: dict[str, str | bool] = {}
    for raw_field in hole_split_fields(line):
        field = raw_field.strip()
        if not field:
            continue
        key, raw_value = hole_split_key_value(field)
        if raw_value is None:
            result[key] = True
        else:
            result[key] = hole_unquote(raw_value)
    return result


def check_invariants() -> None:
    assert parse_kv('a=1; debug; msg="hi; there"') == {'a': '1', 'debug': True, 'msg': 'hi; there'}
    assert parse_kv('') == {}
    assert parse_kv('  ;  ; ') == {}
    assert parse_kv('k=v;;z=') == {'k': 'v', 'z': ''}
    assert parse_kv('q="a\\"b"') == {'q': 'a"b'}
    try:
        parse_kv('msg="oops; x=1')
    except ValueError:
        raised = True
    else:
        raised = False
    assert raised
