def hole_check_closed(in_quotes: bool, escaped: bool, line: str) -> None:
    """Validate the scanner state after the whole line has been consumed.

    Called exactly once, after the scanning loop finishes and before the
    final buffer is flushed.

    Must raise ValueError if the line ends while still inside an open
    double quote (in_quotes is True). Decide, and document in your code,
    how a dangling backslash at end of input (escaped is True) is handled.
    Return None if the line is considered well-formed.
    """
    raise NotImplementedError


def parse_kv(line):
    """Parse a config line like 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons that are not inside double quotes.
    - 'key=value' maps to the value (as a string, with surrounding quotes removed).
    - A bare key with no '=' maps to True.
    - Inside quotes, a backslash escapes the next character (e.g. \" or \\).
    - Raises ValueError for malformed input (see hole_check_closed).
    """
    # Split on semicolons that are outside double quotes.
    parts = []
    buf = []
    in_quotes = False
    escaped = False
    for ch in line:
        if escaped:
            buf.append(ch)
            escaped = False
            continue
        if ch == '\\' and in_quotes:
            escaped = True
            continue
        if ch == '"':
            in_quotes = not in_quotes
            buf.append(ch)
        elif ch == ';' and not in_quotes:
            parts.append(''.join(buf))
            buf = []
        else:
            buf.append(ch)

    hole_check_closed(in_quotes, escaped, line)
    parts.append(''.join(buf))

    result = {}
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if '=' in part:
            key, value = part.split('=', 1)
            key = key.strip()
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            result[key] = value
        else:
            result[part] = True
    return result


def check_invariants():
    assert parse_kv('a=1; debug; msg="hi; there"') == {
        'a': '1', 'debug': True, 'msg': 'hi; there'}
    assert parse_kv('') == {}
    assert parse_kv('debug') == {'debug': True}
    assert parse_kv('a=1;;b=2') == {'a': '1', 'b': '2'}
    assert parse_kv('x="a\\"b"') == {'x': 'a"b'}
    try:
        parse_kv('msg="hi')
        raise AssertionError('unterminated quote should raise ValueError')
    except ValueError:
        pass
