def parse_kv(line: str) -> dict:
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    - Pairs are separated by semicolons that are not inside double quotes.
    - 'key=value' maps to the value as a string.
    - Bare keys (no '=') map to True.
    - Double-quoted values may contain semicolons and '=' characters.
    - Whitespace around keys and unquoted values is stripped.
    - Empty segments (e.g. from a trailing ';') are ignored.
    - Unterminated quoted input is handled by hole_on_unterminated.
    """
    parts = _split_pairs(line)

    result = {}
    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "=" in part:
            key, value = part.split("=", 1)
            key = key.strip()
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = hole_unquote(value[1:-1])
            result[key] = value
        else:
            result[part] = True

    return result


def _split_pairs(line: str) -> list:
    """Split the line on semicolons that are outside double quotes.

    Backslash escapes are recognised inside quotes so that an escaped
    quote does not toggle quoting state. Raw segment text is preserved;
    decoding is left to the caller.
    """
    parts = []
    current = []
    in_quotes = False
    escaped = False

    for ch in line:
        if escaped:
            current.append(ch)
            escaped = False
        elif in_quotes and ch == "\\":
            current.append(ch)
            escaped = True
        elif ch == '"':
            current.append(ch)
            in_quotes = not in_quotes
        elif ch == ";" and not in_quotes:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)

    hole_on_unterminated(in_quotes, escaped)

    parts.append("".join(current))
    return parts


def hole_on_unterminated(in_quotes: bool, escaped: bool) -> None:
    """Decide what happens when input ends in the middle of a quoted value.

    Called once after the whole line has been scanned.

    Must raise ValueError if the input ended while still inside double
    quotes (in_quotes is True). This includes the case where escaped is
    True, i.e. a dangling backslash right before the end of input.

    Must return None (and not raise) when in_quotes is False.
    """
    raise NotImplementedError


