def hole_resolve_column(fieldnames: list[str], column: str) -> str:
    """Return the key from `fieldnames` that identifies `column`."""
    target = column.strip()
    if not target:
        raise KeyError(column)
    # Prefer an exact match, then fall back to a whitespace-insensitive match.
    for name in fieldnames:
        if name == column:
            return name
    for name in fieldnames:
        if name.strip() and name.strip() == target:
            return name
    raise KeyError(column)


def hole_parse_cell(cell: str | None) -> float | None:
    """Convert one raw CSV cell to a float, or signal that it should be skipped."""
    if cell is None:
        return None
    text = cell.strip()
    if not text:
        return None
    return float(text)
