import math

def hole_split_header(rows: list[list[str]]) -> tuple[list[str], list[list[str]]]:
    """Split parsed CSV rows into (header_cells, data_rows).

    The header is the first non-blank row. Blank lines before it are dropped.
    All rows after the header are returned unmodified, including any blank
    lines, since hole_cell_value treats those as missing cells.
    If no non-blank row exists, return ([], []).
    """
    for i, row in enumerate(rows):
        if any(cell.strip() for cell in row):
            return row, rows[i + 1:]
    return [], []


def hole_cell_value(row: list[str], index: int) -> int | float | None:
    """Return the numeric value of row[index], or None if it should be skipped.

    Returns None for a missing cell (index past the end of the row) or a
    cell that is blank after stripping whitespace.

    Non-numeric cells raise ValueError. Silently skipping them would make
    the statistics quietly wrong, so bad data is reported instead. Values
    such as 'nan' and 'inf' are also rejected, because float() accepts them
    and they would corrupt sums and means.
    """
    if index >= len(row):
        return None
    text = row[index].strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        pass
    try:
        value = float(text)
    except ValueError:
        raise ValueError(f'Non-numeric value {text!r} at column index {index}') from None
    if not math.isfinite(value):
        raise ValueError(f'Non-finite value {text!r} at column index {index}')
    return value
