from typing import Optional

def hole_change_inventory(stock: dict[int, int], inserted: list[int]) -> dict[int, int]:
    inventory: dict[int, int] = {}
    for value, count in stock.items():
        if count > 0:
            inventory[value] = count
    # Inserted coins are included: they are added to the machine's stock only
    # after a successful sale, so the customer's own coins can be returned as change.
    for value in inserted:
        inventory[value] = inventory.get(value, 0) + 1
    return inventory

def hole_make_change(amount: int, inventory: dict[int, int]) -> Optional[list[int]]:
    if amount == 0:
        return []
    coins = sorted(
        ((value, count) for value, count in inventory.items() if value > 0 and count > 0),
        reverse=True,
    )
    # best[a] = minimum number of coins summing to a using the coin types processed so far
    # (None means unreachable).
    best: list[Optional[int]] = [None] * (amount + 1)
    best[0] = 0
    stages: list[list[int]] = []
    for value, count in coins:
        new: list[Optional[int]] = [None] * (amount + 1)
        pick = [0] * (amount + 1)
        for a in range(amount + 1):
            for j in range(min(count, a // value) + 1):
                prev = best[a - j * value]
                if prev is None:
                    continue
                cand = prev + j
                if new[a] is None or cand < new[a]:
                    new[a] = cand
                    pick[a] = j
        stages.append(pick)
        best = new
    if best[amount] is None:
        return None
    # Reconstruct the chosen coins by walking the stages backwards.
    result: list[int] = []
    remaining = amount
    for (value, _count), pick in zip(reversed(coins), reversed(stages)):
        j = pick[remaining]
        result.extend([value] * j)
        remaining -= j * value
    assert remaining == 0
    return sorted(result, reverse=True)
