from collections import Counter

def hole_change_pool(inventory, inserted):
    pool = Counter(inventory)
    for c in inserted:
        pool[c] += 1
    return Counter({c: n for c, n in pool.items() if n > 0})

def hole_fewest_change(pool, amount):
    if amount == 0:
        return []
    if amount < 0:
        return None

    coins = sorted((c for c in pool if c > 0 and pool[c] > 0), reverse=True)
    n = len(coins)
    INF = float('inf')

    # best[i][a]: fewest coins from the first i denominations summing to a
    best = [[INF] * (amount + 1) for _ in range(n + 1)]
    take = [[0] * (amount + 1) for _ in range(n + 1)]
    best[0][0] = 0

    for i in range(1, n + 1):
        c = coins[i - 1]
        cnt = pool[c]
        for a in range(amount + 1):
            kmax = min(cnt, a // c)
            for k in range(kmax + 1):
                prev = best[i - 1][a - k * c]
                if prev + k < best[i][a]:
                    best[i][a] = prev + k
                    take[i][a] = k

    if best[n][amount] == INF:
        return None

    result = []
    a = amount
    for i in range(n, 0, -1):
        k = take[i][a]
        c = coins[i - 1]
        result.extend([c] * k)
        a -= k * c
    return result
