from typing import Any, Tuple


def hole_step_policy(value: Any, start: int, end: int) -> Tuple[bool, bool]:
    # A zero-width iteration makes no progress. Retrying from the same
    # position would loop forever, so stop and do not record the value.
    if end == start:
        return (False, False)
    # Real progress: keep the value and try another iteration.
    return (True, True)
