import inspect
from typing import Any, Callable, List


def _accepts_n_positional(f: Callable[..., Any], n: int) -> bool:
    try:
        sig = inspect.signature(f)
    except (TypeError, ValueError):
        return False
    params = list(sig.parameters.values())
    if any(p.kind == p.VAR_POSITIONAL for p in params):
        return True
    positional = [p for p in params
                  if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]
    required = [p for p in positional if p.default is p.empty]
    return len(required) <= n <= len(positional)


def hole_many_empty_values(value: Any) -> List[Any]:
    # An inner match that consumes nothing is not a repetition, so it
    # contributes no items; many() stops looping after this call.
    return []


def hole_map_apply(f: Callable[..., Any], value: Any) -> Any:
    # seq() produces lists. Spread a multi-element list across f's
    # positional parameters only when f actually accepts that many
    # positional arguments; otherwise pass the whole value as one argument.
    if (isinstance(value, list)
            and len(value) >= 2
            and _accepts_n_positional(f, len(value))):
        return f(*value)
    return f(value)
