        ch = line[i]
        if in_quotes and ch == '\\' and i + 1 < n:
            # Keep an escape sequence intact so an escaped quote
            # does not toggle the quoted state.
            current.append(ch)
            current.append(line[i + 1])
            i += 2
            continue
        if ch == '"':
            in_quotes = not in_quotes
            current.append(ch)
        elif ch == ';' and not in_quotes:
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    if in_quotes:
        raise ValueError("unterminated quoted value")
    fields.append(''.join(current))
    return fields


def hole_parse_field(field: str) -> tuple[str, str | bool]:
    if '=' not in field:
        return (field.strip(), True)
    key, value = field.split('=', 1)
    key = key.strip()
    value = value.strip()
    if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
        inner = value[1:-1]
        out: list[str] = []
        j = 0
        while j < len(inner):
            ch = inner[j]
            if ch == '\\' and j + 1 < len(inner) and inner[j + 1] in ('"', '\\'):
                out.append(inner[j + 1])
                j += 2
            else:
                out.append(ch)
                j += 1
        value = ''.join(out)
    return (key, value)
