import heapq


def hole_find_cycle(graph: dict[str, list[str]]) -> list[str] | None:
    color: dict[str, int] = {}  # 0 = unvisited, 1 = on current path, 2 = finished
    for start in sorted(graph):
        if color.get(start, 0) != 0:
            continue
        path: list[str] = [start]
        idx: list[int] = [0]
        color[start] = 1
        while path:
            node = path[-1]
            deps = graph.get(node, [])
            if idx[-1] < len(deps):
                nxt = deps[idx[-1]]
                idx[-1] += 1
                c = color.get(nxt, 0)
                if c == 0:
                    color[nxt] = 1
                    path.append(nxt)
                    idx.append(0)
                elif c == 1:
                    # nxt is on the current path, so path[i] depends on path[i+1]
                    # and the last element depends on nxt.
                    return path[path.index(nxt):]
            else:
                color[node] = 2
                path.pop()
                idx.pop()
    return None


def hole_order_acyclic(graph: dict[str, list[str]]) -> list[str]:
    remaining: dict[str, int] = {}
    dependents: dict[str, list[str]] = {}
    for pkg in graph:
        dependents.setdefault(pkg, [])
    for pkg, reqs in graph.items():
        unique = set(reqs)
        remaining[pkg] = len(unique)
        for dep in unique:
            dependents.setdefault(dep, []).append(pkg)
    ready = [name for name, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order: list[str] = []
    while ready:
        pkg = heapq.heappop(ready)
        order.append(pkg)
        for parent in dependents.get(pkg, []):
            remaining[parent] -= 1
            if remaining[parent] == 0:
                heapq.heappush(ready, parent)
    return order
