def hole_plan_selection(price: int, balance: int, pool: Dict[int, int]) -> Union[List[int], str]:
    if balance < price:
        return 'INSUFFICIENT'
    change = balance - price
    if change == 0:
        return []
    best = None
    max_25 = min(pool.get(25, 0), change // 25)
    for a in range(max_25 + 1):
        rest_a = change - 25 * a
        max_10 = min(pool.get(10, 0), rest_a // 10)
        for b in range(max_10 + 1):
            rem = rest_a - 10 * b
            if rem < 0 or rem % 5 != 0:
                continue
            n5 = rem // 5
            if n5 > pool.get(5, 0):
                continue
            total = a + b + n5
            if best is None or total < best[0]:
                best = (total, a, b, n5)
    if best is None:
        return 'NO_CHANGE'
    _, a, b, n5 = best
    return [25] * a + [10] * b + [5] * n5

def hole_absorb_payment(inventory: Dict[int, int], inserted: List[int], change: List[int]) -> Dict[int, int]:
    new_inv = dict(inventory)
    for coin in inserted:
        new_inv[coin] = new_inv.get(coin, 0) + 1
    for coin in change:
        new_inv[coin] = new_inv.get(coin, 0) - 1
    return new_inv
