import re


def top_k_words(text, k):
    if k <= 0:
        return []
    counts = {}
    for word in re.findall(r"[A-Za-z]+", text.lower()):
        counts[word] = counts.get(word, 0) + 1
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:k]
