def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            tokens.append(('num', int(text[i:j])))
            i = j
        elif c in '+-*/%^()':
            tokens.append((c, c))
            i += 1
        else:
            raise SyntaxError(f"invalid character {c!r} at position {i}")
    return tokens


