class Editor:
    """A simple text editor with a cursor and undo/redo history."""

    def __init__(self, text: str = "") -> None:
        self._text = text
        self._cursor = len(text)
        self._undo_stack: list[tuple[str, int]] = []
        self._redo_stack: list[tuple[str, int]] = []

    @property
    def text(self) -> str:
        return self._text

    @property
    def cursor(self) -> int:
        return self._cursor

    def _snapshot(self) -> tuple[str, int]:
        return (self._text, self._cursor)

    def _record(self, before: tuple[str, int]) -> None:
        self._undo_stack.append(before)
        self._redo_stack.clear()

    def insert(self, s: str) -> None:
        """Insert string s at the cursor and move the cursor past it."""
        if not s:
            return
        before = self._snapshot()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)
        self._record(before)

    def delete(self, n: int = 1) -> None:
        """Backspace: delete up to n characters before the cursor."""
        if n < 0:
            raise ValueError("n must be non-negative")
        count = min(n, self._cursor)
        if count == 0:
            return
        before = self._snapshot()
        start = self._cursor - count
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start
        self._record(before)

    def move(self, pos: int) -> None:
        """Move the cursor to pos, clamped to the valid range [0, len(text)]."""
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        """Undo the last edit. Returns True if anything was undone."""
        if not self._undo_stack:
            return False
        self._redo_stack.append(self._snapshot())
        self._text, self._cursor = self._undo_stack.pop()
        return True

    def redo(self) -> bool:
        """Redo the last undone edit. Returns True if anything was redone."""
        if not self._redo_stack:
            return False
        self._undo_stack.append(self._snapshot())
        self._text, self._cursor = self._redo_stack.pop()
        return True
