def hole_digit_points(n):
    """Return the point value of a single integer n (an int, possibly negative or zero)."""
    if n == 0:
        return 0
    digits = str(abs(n))
    if n < 0:
        return -int(digits[0]) + sum(int(d) for d in digits[1:])
    return sum(int(d) for d in digits)


def hole_sort_key(index, n):
    """Return the sort key for the element n found at position index in the input list."""
    return (hole_digit_points(n), index)
