def hole_precedence(op: str) -> int:
    """Return the binding strength of `op`; a higher value binds more tightly."""
    if op in ('+', '-'):
        return 1
    if op in ('*', '//'):
        return 2
    if op == '**':
        return 3
    raise ValueError(f'unsupported operator: {op!r}')


def hole_apply(op: str, left, right):
    """Apply the binary operator `op` to `left` and `right` and return the result."""
    if op == '+':
        return left + right
    if op == '-':
        return left - right
    if op == '*':
        return left * right
    if op == '//':
        return left // right
    if op == '**':
        return left ** right
    raise ValueError(f'unsupported operator: {op!r}')


def hole_reduce(tokens: list):
    """Evaluate a flat token list [operand, op, operand, op, ..., operand]."""
    values = [tokens[0]]
    ops = []

    def _reduce_top():
        op = ops.pop()
        right = values.pop()
        left = values.pop()
        values.append(hole_apply(op, left, right))

    for i in range(1, len(tokens), 2):
        op = tokens[i]
        val = tokens[i + 1]
        np = hole_precedence(op)
        while ops:
            tp = hole_precedence(ops[-1])
            # Left-associative operators reduce on equal precedence;
            # '**' is right-associative and does not.
            if tp > np or (tp == np and op != '**'):
                _reduce_top()
            else:
                break
        ops.append(op)
        values.append(val)

    while ops:
        _reduce_top()
    return values[0]
```

