from typing import List, Set, Tuple

Cell = Tuple[int, int]

def hole_initial_frontier(grid: List[List[int]]) -> Set[Cell]:
    # hole_step always moves to a neighbour of the frontier, so the first
    # call can only land on the minimum cell if the frontier holds its
    # neighbours. This models a virtual cell just before the start.
    n = len(grid)
    lo = min(min(row) for row in grid)
    starts = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == lo]
    frontier: Set[Cell] = set()
    for r, c in starts:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                frontier.add((nr, nc))
    return frontier

def hole_step(grid: List[List[int]], frontier: Set[Cell]) -> Tuple[int, Set[Cell]]:
    n = len(grid)
    candidates: Set[Cell] = set()
    for r, c in frontier:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                candidates.add((nr, nc))
    value = min(grid[r][c] for r, c in candidates)
    next_frontier = {(r, c) for r, c in candidates if grid[r][c] == value}
    return value, next_frontier
