def hole_is_nested(value) -> bool:
    """Return True if `value` should be recursed into, False if it is a leaf."""
    return isinstance(value, (list, tuple))


def hole_flatten_into(value, out: list) -> None:
    """Append the flattened leaves of `value` to the list `out` in place."""
    if not hole_is_nested(value):
        out.append(value)
        return

    # Explicit stack of iterators, so nesting depth is not limited by recursion.
    stack = [iter(value)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if hole_is_nested(item):
            stack.append(iter(item))
        else:
            out.append(item)
```

