    text = s.strip()
    if text.startswith('+'):
        text = text[1:]
    if not text:
        raise ValueError('empty phone number')
    for ch in text:
        if ch not in _ALLOWED_CHARS:
            raise ValueError(f'invalid character {ch!r} in phone number: {s!r}')
