def hole_split_fields(line: str) -> list[str]:
    """Split a config line into raw field strings at top-level semicolons."""
    fields: list[str] = []
    buf: list[str] = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '\\' and i + 1 < n:
                # Keep the escape pair intact; it cannot end the quote or split.
                buf.append(c)
                buf.append(line[i + 1])
                i += 2
                continue
            if c == '"':
                in_quotes = False
            buf.append(c)
        else:
            if c == '"':
                in_quotes = True
                buf.append(c)
            elif c == ';':
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(c)
        i += 1
    if in_quotes:
        raise ValueError("unterminated quoted value")
    fields.append(''.join(buf))
    return fields


def hole_parse_field(field: str) -> tuple[str, str | bool]:
    """Interpret one stripped, non-empty raw field as a (key, value) pair."""
    eq = field.find('=')
    if eq == -1:
        return field.strip(), True

    key = field[:eq].strip()
    raw = field[eq + 1:].lstrip()

    if raw.startswith('"'):
        chars: list[str] = []
        i = 1
        n = len(raw)
        closed = False
        while i < n:
            c = raw[i]
            if c == '\\' and i + 1 < n and raw[i + 1] in '"\\':
                chars.append(raw[i + 1])
                i += 2
                continue
            if c == '"':
                closed = True
                i += 1
                break
            chars.append(c)
            i += 1
        if not closed:
            raise ValueError("unterminated quoted value")
        if raw[i:].strip():
            raise ValueError("unexpected text after closing quote")
        return key, ''.join(chars)

    return key, raw.strip()
