from __future__ import annotations

def hole_make_change(amount: int, stock: dict[int, int]) -> list[int] | None:
    if amount == 0:
        return []
    if amount < 0 or amount % 5 != 0:
        return None
    best = None
    max25 = min(stock.get(25, 0), amount // 25)
    for c25 in range(max25, -1, -1):
        rem25 = amount - 25 * c25
        max10 = min(stock.get(10, 0), rem25 // 10)
        for c10 in range(max10, -1, -1):
            rem = rem25 - 10 * c10
            c5 = rem // 5
            if c5 <= stock.get(5, 0):
                total = c25 + c10 + c5
                if best is None or total < best[0]:
                    best = (total, c25, c10, c5)
    if best is None:
        return None
    _, n25, n10, n5 = best
    return [25] * n25 + [10] * n10 + [5] * n5

def hole_change_stock(stock: dict[int, int], inserted: list[int]) -> dict[int, int]:
    return {c: stock.get(c, 0) + inserted.count(c) for c in (5, 10, 25)}
