from bisect import insort


def hole_is_valid_interval(start, end) -> bool:
    """Return True iff [start, end) is a legal interval to book or cancel."""
    return bool(start < end)


def hole_overlaps(a_start, a_end, b_start, b_end) -> bool:
    """Return True iff the half-open intervals [a_start, a_end) and [b_start, b_end)
    share at least one point. Touching intervals do not overlap."""
    return bool(a_start < b_end and b_start < a_end)


def hole_cancel_matches(booking, start, end) -> bool:
    """Return True iff the stored booking is exactly (start, end).

    Matching rule: exact match on both endpoints.
    """
    return bool(booking[0] == start and booking[1] == end)


def hole_free_gaps(bookings, lo, hi, min_len) -> list:
    """Return the free gaps inside [lo, hi) of length >= min_len, sorted by start.

    Bookings are clipped to the window. Walks the sorted bookings with a cursor
    that starts at lo; any space between the cursor and the next clipped booking
    is a gap. Touching bookings produce no gap between them.
    """
    gaps = []
    cursor = lo
    for b_start, b_end in bookings:
        if b_end <= lo or b_start >= hi:
            continue
        clipped_start = max(b_start, lo)
        clipped_end = min(b_end, hi)
        if clipped_start > cursor:
            gaps.append((cursor, clipped_start))
        cursor = max(cursor, clipped_end)
    if cursor < hi:
        gaps.append((cursor, hi))
    return [(s, e) for (s, e) in gaps if e - s >= min_len]
