from typing import Tuple


def hole_binding_power(op: str) -> Tuple[int, bool]:
    table = {
        '+': (1, False),
        '-': (1, False),
        '*': (2, False),
        '/': (2, False),
        '%': (2, False),
        '^': (4, True),
    }
    if op not in table:
        raise SyntaxError(f'unknown binary operator {op!r}')
    return table[op]


def hole_apply_binary(op: str, lhs: int, rhs: int) -> int:
    if op == '+':
        return lhs + rhs
    if op == '-':
        return lhs - rhs
    if op == '*':
        return lhs * rhs
    if op == '/':
        if rhs == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(lhs) // abs(rhs)
        return q if (lhs < 0) == (rhs < 0) else -q
    if op == '%':
        if rhs == 0:
            raise ZeroDivisionError('remainder by zero')
        r = abs(lhs) % abs(rhs)
        return -r if lhs < 0 else r
    if op == '^':
        if rhs < 0:
            raise ValueError('negative exponent')
        return lhs ** rhs
    raise SyntaxError(f'unknown binary operator {op!r}')


def hole_parse_expression(tokens: list) -> int:
    # Unary minus binds looser than '^' (so -2^2 == -(2^2)) and tighter than
    # '*', '/', '%'. The operand of unary minus is parsed at '^' precedence,
    # and '^' is right-associative with a unary-minus-capable exponent (2^-1).
    pos = 0
    n = len(tokens)

    def peek():
        return tokens[pos] if pos < n else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr(min_prec: int) -> int:
        lhs = parse_unary()
        while True:
            tok = peek()
            if tok is None or tok.kind != 'op':
                break
            prec, right = hole_binding_power(tok.value)
            if prec < min_prec:
                break
            advance()
            next_min = prec if right else prec + 1
            rhs = parse_expr(next_min)
            lhs = hole_apply_binary(tok.value, lhs, rhs)
        return lhs

    def parse_unary() -> int:
        tok = peek()
        if tok is not None and tok.kind == 'op' and tok.value == '-':
            advance()
            caret_prec, _ = hole_binding_power('^')
            operand = parse_expr(caret_prec)
            return -operand
        return parse_atom()

    def parse_atom() -> int:
        tok = peek()
        if tok is None:
            raise SyntaxError('unexpected end of input')
        if tok.kind == 'num':
            advance()
            return int(tok.value)
        if tok.kind == 'lp':
            advance()
            value = parse_expr(1)
            closing = peek()
            if closing is None or closing.kind != 'rp':
                raise SyntaxError('unbalanced parentheses: missing ")"')
            advance()
            return value
        if tok.kind == 'rp':
            raise SyntaxError('unbalanced parentheses: unexpected ")"')
        raise SyntaxError(f'unexpected token {tok.value!r}')

    if n == 0:
        raise SyntaxError('empty expression')
    result = parse_expr(1)
    if pos != n:
        raise SyntaxError(f'unexpected trailing token {tokens[pos].value!r}')
    return result
