from typing import List


def hole_pack_words(words: List[str], width: int) -> List[str]:
    """Greedily pack words into lines of at most `width` characters."""
    lines: List[str] = []
    current = None
    for word in words:
        if current is None:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    if current is not None:
        lines.append(current)
    return lines


def hole_split_long_word(word: str, width: int) -> List[str]:
    """Split a word that is longer than `width` into pieces that fit a line."""
    return [word[i:i + width] for i in range(0, len(word), width)]
