from typing import Dict, Hashable, Iterable, List, Optional, Set, Tuple

Node = Hashable
Adjacency = Dict[Node, Set[Node]]
Assignment = Dict[Node, int]


def hole_select_next(uncolored: Set[Node], adjacency: Adjacency, assignment: Assignment) -> Node:
    """Pick the most constrained uncolored node: most distinct colors already
    used by colored neighbours first, then most uncolored neighbours."""
    def key(node: Node) -> Tuple[int, int]:
        used = {assignment[nb] for nb in adjacency[node] if nb in assignment}
        open_degree = sum(1 for nb in adjacency[node] if nb in uncolored)
        return (-len(used), -open_degree)

    return min(uncolored, key=key)


def hole_candidate_colors(node: Node, adjacency: Adjacency, assignment: Assignment, k: int) -> List[int]:
    """Return every color in range(k) not used by an already-assigned neighbour."""
    forbidden = {assignment[nb] for nb in adjacency[node] if nb in assignment}
    return [color for color in range(k) if color not in forbidden]


def hole_search(uncolored: Set[Node], adjacency: Adjacency, assignment: Assignment, k: int) -> Optional[Assignment]:
    """Exhaustive backtracking search over the uncolored nodes."""
    if not uncolored:
        return assignment

    node = hole_select_next(uncolored, adjacency, assignment)
    uncolored.remove(node)
    for color in hole_candidate_colors(node, adjacency, assignment, k):
        assignment[node] = color
        result = hole_search(uncolored, adjacency, assignment, k)
        if result is not None:
            return result
        del assignment[node]
    uncolored.add(node)
    return None
