from typing import Dict, Hashable, Iterable, List, Optional, Set, Tuple

Node = Hashable


def hole_pick_next_node(uncolored: Set[Node], adj: Dict[Node, Set[Node]], assignment: Dict[Node, int], k: int) -> Node:
    """Choose which uncolored node to color next (most constrained first)."""
    def key(n: Node):
        used = {assignment[m] for m in adj[n] if m in assignment}
        remaining = k - len(used)
        uncolored_deg = sum(1 for m in adj[n] if m in uncolored)
        return (remaining, -uncolored_deg, repr(n))
    return min(uncolored, key=key)


def hole_color_order(node: Node, adj: Dict[Node, Set[Node]], assignment: Dict[Node, int], k: int) -> List[int]:
    """Return every color in range(k) exactly once, least-constraining first."""
    used = {assignment[m] for m in adj[node] if m in assignment}

    # Precompute, for each uncolored neighbour, which colors it still has free.
    neighbour_forbidden: List[Set[int]] = []
    for m in adj[node]:
        if m not in assignment:
            neighbour_forbidden.append({assignment[x] for x in adj[m] if x in assignment})

    def pressure(c: int) -> int:
        # Number of uncolored neighbours that would lose color c as an option.
        return sum(1 for forb in neighbour_forbidden if c not in forb)

    return sorted(range(k), key=lambda c: (c in used, pressure(c), c))
