    for line in text.splitlines():
        stripped = line.strip()
        if stripped:
            current.append(stripped)
        elif current:
            paragraphs.append("\n".join(current))
            current = []
    if current:
        paragraphs.append("\n".join(current))
    return paragraphs

def hole_fill_paragraph(paragraph: str, width: int) -> List[str]:
    pieces: List[str] = []
    for word in paragraph.split():
        for i in range(0, len(word), width):
            pieces.append(word[i:i + width])

    lines: List[str] = []
    line = ""
    for piece in pieces:
        if not line:
            line = piece
        elif len(line) + 1 + len(piece) <= width:
            line += " " + piece
        else:
            lines.append(line)
            line = piece
    if line:
        lines.append(line)
    return lines

def wrap_text(text: str, width: int) -> str:
    """Word-wrap `text` to `width`, keeping paragraphs separate.

    Paragraphs are separated by a single blank line in the output. Each
    paragraph is wrapped independently using the greedy strategy. Raises
    ValueError if `width` is less than 1.
    """
    if width < 1:
        raise ValueError('width must be at least 1')
    paragraphs = hole_split_paragraphs(text)
    wrapped_blocks = []
    for paragraph in paragraphs:
        lines = hole_fill_paragraph(paragraph, width)
        wrapped_blocks.append('\n'.join(lines))
    return '\n\n'.join(wrapped_blocks)
