def hole_all_packages(graph: dict[str, list[str]]) -> set[str]:
    """Return the set of every package that must appear in the output."""
    packages: set[str] = set(graph)
    for requires in graph.values():
        packages.update(requires)
    return packages


def hole_pick_next(ready: set[str]) -> str:
    """Return the alphabetically smallest package in `ready`."""
    return min(ready)


def hole_find_cycle(stuck: dict[str, list[str]]) -> list[str]:
    """Return one dependency cycle among the packages that cannot be installed."""
    path: list[str] = []
    position: dict[str, int] = {}
    current = min(stuck)
    while current not in position:
        position[current] = len(path)
        path.append(current)
        current = stuck[current][0]
    start = position[current]
    return path[start:] + [current]
