    """Return the cursor position that move(pos) should actually store."""
    if pos < 0:
        return 0
    if pos > text_length:
        return text_length
    return pos

def hole_apply_delete(text: str, cursor: int, n: int) -> tuple:
    """Perform a backspace of n characters ending at the cursor."""
    if n <= 0 or cursor <= 0:
        return (text, cursor)
    count = min(n, cursor)
    new_cursor = cursor - count
    new_text = text[:new_cursor] + text[cursor:]
    return (new_text, new_cursor)

def hole_history_entry_changed(before: tuple, after: tuple) -> bool:
    """Decide whether a state change should be recorded as an undo step.

    Only edits that change the text are recorded. Moves change only the
    cursor, so they are excluded, and a no-op delete or empty insert leaves
    the text unchanged, so it is excluded too.
    """
    before_text, _ = before
    after_text, _ = after
    return before_text != after_text
