from typing import List, Set, Tuple

def hole_initial_frontier(grid: List[List[int]]) -> Set[Tuple[int, int]]:
    # hole_step reports the value of a neighbour of the frontier, so the
    # first emitted value is one step past the frontier. To make the first
    # emitted value the global minimum (the cell holding the smallest value),
    # seed the frontier with the neighbours of that minimum cell. Every such
    # neighbour is adjacent to the minimum cell, so the first step yields
    # the minimum value and lands exactly on that cell.
    n = len(grid)
    best_r, best_c = 0, 0
    for r in range(n):
        for c in range(n):
            if grid[r][c] < grid[best_r][best_c]:
                best_r, best_c = r, c
    result: Set[Tuple[int, int]] = set()
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = best_r + dr, best_c + dc
        if 0 <= nr < n and 0 <= nc < n:
            result.add((nr, nc))
    return result

def hole_step(grid: List[List[int]], frontier: Set[Tuple[int, int]]) -> Tuple[int, Set[Tuple[int, int]]]:
    n = len(grid)
    candidates: Set[Tuple[int, int]] = set()
    for r, c in frontier:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                candidates.add((nr, nc))
    value = min(grid[r][c] for r, c in candidates)
    next_frontier = {(r, c) for r, c in candidates if grid[r][c] == value}
    return (value, next_frontier)
