                best_r, best_c = r, c
    result: Set[Tuple[int, int]] = set()
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = best_r + dr, best_c + dc
        if 0 <= nr < n and 0 <= nc < n:
            result.add((nr, nc))
    return result

def hole_step(grid: List[List[int]], frontier: Set[Tuple[int, int]]) -> Tuple[int, Set[Tuple[int, int]]]:
    n = len(grid)
    candidates: Set[Tuple[int, int]] = set()
    for r, c in frontier:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                candidates.add((nr, nc))
    value = min(grid[r][c] for r, c in candidates)
    next_frontier = {(r, c) for r, c in candidates if grid[r][c] == value}
    return (value, next_frontier)
