def hole_precedence(op: str) -> int:
    """Return the binding strength of `op`; a higher value binds more tightly."""
    if op in ('+', '-'):
        return 1
    if op in ('*', '//'):
        return 2
    if op == '**':
        return 3
    raise ValueError(f'unsupported operator: {op!r}')


def hole_apply(op: str, left, right):
    """Apply the binary operator `op` to `left` and `right` and return the result."""
    if op == '+':
        return left + right
    if op == '-':
        return left - right
    if op == '*':
        return left * right
    if op == '//':
        return left // right
    if op == '**':
        return left ** right
    raise ValueError(f'unsupported operator: {op!r}')


def hole_reduce(tokens: list):
    """Evaluate a flat token list [operand, op, operand, op, ..., operand]."""
    values = [tokens[0]]
    ops = []

    def reduce_once():
        op = ops.pop()
        right = values.pop()
        left = values.pop()
        values.append(hole_apply(op, left, right))

    for i in range(1, len(tokens), 2):
        op = tokens[i]
        value = tokens[i + 1]
        p = hole_precedence(op)
        while ops:
            top = ops[-1]
            top_p = hole_precedence(top)
            # '**' is right-associative, so equal precedence does not reduce it.
            if top_p > p or (top_p == p and op != '**'):
                reduce_once()
            else:
                break
        ops.append(op)
        values.append(value)

    while ops:
        reduce_once()
    return values[0]
```

