def hole_row_key(row: list[float]) -> float:
    """Return the value by which `row` should be ordered.

    Must return the sum of all elements of `row` as a number.
    An empty row has key 0. The function must not modify `row`.
    """
    return sum(row)


def hole_order_indices(keys: list[float]) -> list[int]:
    """Return a permutation of range(len(keys)) listing indices in ascending key order.

    `keys[i]` is the key of row i. The result must satisfy:
      - keys[result[j]] <= keys[result[j+1]] for every valid j;
      - ties are broken by original index (smaller index first), i.e. the sort is stable;
      - every index 0..len(keys)-1 appears exactly once.
    For an empty list, return [].
    """
    return sorted(range(len(keys)), key=lambda i: keys[i])
```

