from typing import Any


def hole_is_container(obj: Any) -> bool:
    """Return True if obj must be descended into, False if it is a leaf."""
    try:
        return isinstance(obj, (list, tuple))
    except Exception:
        return False


def hole_collect(item: Any, out: list) -> None:
    """Append the leaves of item to out, in left-to-right order."""
    if not hole_is_container(item):
        out.append(item)
        return

    # Iterative traversal with an explicit stack of iterators, so nesting
    # depth is not limited by the Python recursion limit.
    stack = [iter(item)]
    while stack:
        try:
            child = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if hole_is_container(child):
            stack.append(iter(child))
        else:
            out.append(child)
