def hole_extract_digits(s: str) -> str:
    """Return the digits of `s` as a string containing only '0'-'9'.

    Formatting characters (spaces, '-', '.', '(', ')') are removed.
    A single leading '+' is allowed only when immediately followed by
    the country code '1'; any other '+' placement is an error.
    Raise ValueError if `s` contains any other character, including
    letters, or if the '+' rule is violated. Return an empty string
    only if `s` has no digits at all (the caller will reject that).
    """
    if '+' in s:
        if not s.startswith('+1'):
            raise ValueError(f'invalid use of "+" in {s!r}')
        # Drop the '+' only; the '1' stays as a digit.
        s = s[1:]
    if '+' in s:
        raise ValueError(f'invalid use of "+" in {s!r}')

    out = []
    for ch in s:
        if ch in '0123456789':
            out.append(ch)
        elif ch in ' -.()':
            continue
        else:
            raise ValueError(f'invalid character {ch!r} in {s!r}')
    return ''.join(out)


def hole_national_number(digits: str) -> str:
    """Return the 10-digit NANP national number from `digits`.

    `digits` is the output of hole_extract_digits. Accept exactly
    10 digits, or 11 digits whose first digit is '1' (country code,
    which must be dropped from the result). Raise ValueError for any
    other length. Also raise ValueError if the area code (first digit
    of the national number) or the exchange (fourth digit) is '0' or '1'.
    """
    if len(digits) == 11 and digits[0] == '1':
        national = digits[1:]
    elif len(digits) == 10:
        national = digits
    else:
        raise ValueError(f'expected 10 digits (or 11 with leading 1), got {len(digits)}')

    if any(ch not in '0123456789' for ch in national):
        raise ValueError(f'non-digit characters in {digits!r}')

    if national[0] in '01':
        raise ValueError(f'invalid area code starting with {national[0]!r}')
    if national[3] in '01':
        raise ValueError(f'invalid exchange code starting with {national[3]!r}')

    return national
```

