def hole_split_fields(line: str) -> list[str]:
    """Split a config line into raw field strings at top-level semicolons."""
    fields: list[str] = []
    buf: list[str] = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == "\\" and i + 1 < n:
                buf.append(ch)
                buf.append(line[i + 1])
                i += 2
                continue
            if ch == '"':
                in_quotes = False
            buf.append(ch)
        else:
            if ch == '"':
                in_quotes = True
                buf.append(ch)
            elif ch == ";":
                fields.append("".join(buf))
                buf = []
            else:
                buf.append(ch)
        i += 1
    fields.append("".join(buf))
    return fields


def hole_parse_field(field: str) -> tuple[str, str | bool]:
    """Interpret one stripped, non-empty raw field as a (key, value) pair."""
    if "=" not in field:
        return field.strip(), True

    key, _, rest = field.partition("=")
    key = key.strip()
    rest_l = rest.lstrip()

    if rest_l.startswith('"'):
        out: list[str] = []
        i = 1
        n = len(rest_l)
        end = -1
        while i < n:
            ch = rest_l[i]
            if ch == "\\" and i + 1 < n and rest_l[i + 1] in '"\\':
                out.append(rest_l[i + 1])
                i += 2
                continue
            if ch == '"':
                end = i + 1
                break
            out.append(ch)
            i += 1
        if end < 0:
            raise ValueError(f"unterminated quoted value in field: {field!r}")
        tail = rest_l[end:]
        if tail.strip():
            raise ValueError(f"unexpected text after quoted value: {tail!r}")
        return key, "".join(out)

    if '"' in rest:
        raise ValueError(f"unexpected quote in unquoted value: {field!r}")
    return key, rest.strip()
```

