                buf = []
            else:
                if ch == '"':
                    in_quote = True
                buf.append(ch)
        i += 1
    if in_quote:
        raise ValueError('unterminated quoted value in config line')
    fields.append(''.join(buf).strip())
    return fields

def hole_parse_field(field: str) -> tuple[str, Union[str, bool]]:
    if '=' not in field:
        return (field, True)
    key, _, value = field.partition('=')
    key = key.strip()
    value = value.strip()
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        inner = value[1:-1]
        out: list[str] = []
        j = 0
        while j < len(inner):
            c = inner[j]
            if c == '\\' and j + 1 < len(inner) and inner[j + 1] in '"\\':
                out.append(inner[j + 1])
                j += 2
            else:
                out.append(c)
                j += 1
        value = ''.join(out)
    return (key, value)
