def hole_header_index(rows: list[list[str]]) -> int:
    """Return the index into `rows` of the row to use as the header."""
    for i, row in enumerate(rows):
        if any(cell.strip() != '' for cell in row):
            return i
    raise ValueError("no row can serve as a header")

def hole_column_index(header: list[str], column: str) -> int:
    """Return the index of `column` within `header`."""
    for i, cell in enumerate(header):
        if cell == column:
            return i
    raise KeyError(column)

