    """Convert one non-empty CSV cell into a float."""
    return float(text.strip())

def hole_summarize(values: list[float]) -> dict:
    """Summarize a list of parsed numeric values (the list may be empty)."""
    count = len(values)
    if count == 0:
        return {"count": 0, "sum": 0.0, "mean": None, "min": None, "max": None}
    total = sum(values, 0.0)
    return {
        "count": count,
        "sum": total,
        "mean": total / count,
        "min": min(values),
        "max": max(values),
    }
