from typing import Optional

def hole_skip_leading_blank_lines(csv_text: str) -> str:
    """Return csv_text with leading blank lines removed.

    The first line of the result must be the first non-blank line of
    csv_text, with all content after it unchanged. A line is blank if it
    contains only whitespace. Returns '' if every line is blank.
    """
    lines = csv_text.splitlines(keepends=True)
    for index, line in enumerate(lines):
        if line.strip():
            return ''.join(lines[index:])
    return ''

def hole_parse_cell(raw: str) -> Optional[float]:
    """Convert one raw CSV cell into a float.

    Returns None if the cell should be skipped (empty or whitespace-only).
    Returns the cell's numeric value as a float otherwise, ignoring
    leading and trailing whitespace.
    Raises ValueError if the cell is non-empty and not numeric.
    """
    stripped = raw.strip()
    if not stripped:
        return None
    return float(stripped)

def hole_extremes(values: list[float]) -> tuple[Optional[float], Optional[float]]:
    """Return (minimum, maximum) of the given values.

    Returns (None, None) if values is empty.
    Otherwise returns the smallest and largest value in values.
    """
    if not values:
        return (None, None)
    return (min(values), max(values))

def hole_mean(total: float, count: int) -> Optional[float]:
    """Return the arithmetic mean of a set of values.

    Returns None if count is 0.
    Otherwise returns total / count as a float.
    """
    if count == 0:
        return None
    return float(total) / count
