from collections import OrderedDict
from typing import Any, Hashable, Optional

def hole_expires_at(written_at: float, ttl: float) -> float:
    return written_at + ttl

def hole_is_expired(expires_at: float, now: float) -> bool:
    return now >= expires_at

def hole_victim(entries: 'OrderedDict[Hashable, tuple[Any, float]]', now: float) -> Optional[Hashable]:
    if not entries:
        return None
    last = next(reversed(entries))
    if len(entries) == 1:
        return last
    for key, (_, expires_at) in entries.items():
        if key == last:
            continue
        if hole_is_expired(expires_at, now):
            return key
    for key in entries:
        if key != last:
            return key
    return None
