from typing import List, Tuple


def hole_binding_power(op: str) -> Tuple[int, bool]:
    """
    Return (precedence, right_assoc) for a binary operator.

    Unary minus sits between '^' and '*' '/' '%' (precedence 3); it is handled
    in hole_parse_expression, not here.
    """
    table = {
        '+': (1, False),
        '-': (1, False),
        '*': (2, False),
        '/': (2, False),
        '%': (2, False),
        '^': (4, True),
    }
    if op not in table:
        raise SyntaxError(f'unknown operator {op!r}')
    return table[op]


def _trunc_div(a: int, b: int) -> int:
    """Integer division truncating toward zero (C semantics). b must be nonzero."""
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def hole_apply_binary(op: str, lhs: int, rhs: int) -> int:
    """Apply a binary operator with C-style integer division and remainder."""
    if op == '+':
        return lhs + rhs
    if op == '-':
        return lhs - rhs
    if op == '*':
        return lhs * rhs
    if op == '/':
        if rhs == 0:
            raise ZeroDivisionError('division by zero')
        return _trunc_div(lhs, rhs)
    if op == '%':
        if rhs == 0:
            raise ZeroDivisionError('remainder by zero')
        return lhs - _trunc_div(lhs, rhs) * rhs
    if op == '^':
        if rhs < 0:
            raise ValueError('negative exponent')
        return lhs ** rhs
    raise SyntaxError(f'unknown operator {op!r}')


def hole_parse_expression(tokens: List['Token']) -> int:
    """
    Parse the token list as a complete arithmetic expression and return its value.

    Unary minus binds looser than '^', so -2^2 == -(2^2) == -4, while the
    exponent of '^' may itself carry a unary minus (2^-1 parses, then raises
    ValueError for the negative exponent).
    """
    if not tokens:
        raise SyntaxError('empty expression')

    pos = 0
    power_prec = hole_binding_power('^')[0]

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_primary() -> int:
        tok = peek()
        if tok is None:
            raise SyntaxError('unexpected end of input')
        if tok.kind == 'num':
            advance()
            return int(tok.value)
        if tok.kind == 'lp':
            advance()
            value = parse_binary(1)
            nxt = peek()
            if nxt is None or nxt.kind != 'rp':
                raise SyntaxError('unbalanced parentheses: missing ")"')
            advance()
            return value
        raise SyntaxError(f'unexpected token {tok.value!r}')

    def parse_unary() -> int:
        tok = peek()
        if tok is not None and tok.kind == 'op' and tok.value == '-':
            advance()
            # Operand takes only '^' operators, so -2^2 == -(2^2).
            return -parse_binary(power_prec)
        return parse_primary()

    def parse_binary(min_prec: int) -> int:
        lhs = parse_unary()
        while True:
            tok = peek()
            if tok is None or tok.kind != 'op':
                break
            prec, right_assoc = hole_binding_power(tok.value)
            if prec < min_prec:
                break
            advance()
            rhs = parse_binary(prec if right_assoc else prec + 1)
            lhs = hole_apply_binary(tok.value, lhs, rhs)
        return lhs

    result = parse_binary(1)
    if pos != len(tokens):
        raise SyntaxError(f'unexpected trailing token {tokens[pos].value!r}')
    return result
