def hole_is_valid_interval(start, end) -> bool:
    """Return True iff [start, end) is a legal interval to book or cancel."""
    return bool(start < end)


def hole_overlaps(a_start, a_end, b_start, b_end) -> bool:
    """Return True iff the half-open intervals [a_start, a_end) and
    [b_start, b_end) share at least one point. Touching intervals do not overlap."""
    return bool(a_start < b_end and b_start < a_end)


def hole_cancel_matches(booking, start, end) -> bool:
    """Match only a booking whose start and end are exactly (start, end)."""
    return bool(booking[0] == start and booking[1] == end)


def hole_free_gaps(bookings, lo, hi, min_len) -> list:
    """Return the maximal free gaps inside [lo, hi) with length >= min_len,
    sorted by start. Bookings are clipped to the window."""
    gaps = []
    cursor = lo
    for b_start, b_end in bookings:
        if b_start >= hi:
            break
        if b_end <= cursor:
            continue
        s = max(b_start, lo)
        e = min(b_end, hi)
        if s > cursor:
            gaps.append((cursor, s))
        cursor = max(cursor, e)
    if cursor < hi:
        gaps.append((cursor, hi))
    return [(g_start, g_end) for g_start, g_end in gaps if g_end - g_start >= min_len]
