from typing import Dict, List, Optional, Union


def hole_change_for(amount: int, inventory: Dict[int, int]) -> Optional[List[int]]:
    if amount < 0:
        return None
    if amount == 0:
        return []
    if amount % 5 != 0:
        return None

    best = None
    max_a = min(inventory.get(25, 0), amount // 25)
    for a in range(max_a, -1, -1):
        rem = amount - 25 * a
        max_b = min(inventory.get(10, 0), rem // 10)
        for b in range(max_b, -1, -1):
            rem2 = rem - 10 * b
            c = rem2 // 5  # rem2 is a multiple of 5 because amount is
            if c <= inventory.get(5, 0):
                total = a + b + c
                if best is None or total < best[0]:
                    best = (total, a, b, c)

    if best is None:
        return None
    _, a, b, c = best
    return [25] * a + [10] * b + [5] * c


def hole_select_result(price: int, inserted: List[int], inventory: Dict[int, int]) -> Union[List[int], str]:
    balance = sum(inserted)
    if balance < price:
        return 'INSUFFICIENT'

    # Policy: coins inserted in this transaction are added to the inventory
    # and may be used to make change.
    combined = dict(inventory)
    for coin in inserted:
        combined[coin] = combined.get(coin, 0) + 1

    change = hole_change_for(balance - price, combined)
    if change is None:
        return 'NO_CHANGE'
    return change
