from collections import Counter
from typing import List, Optional


def hole_change_pool(stock: Counter, inserted: Counter) -> Counter:
    """Coins usable for change: the machine's stock plus the customer's
    inserted coins for this transaction."""
    pool = Counter()
    for denom, count in stock.items():
        if count > 0:
            pool[denom] += count
    for denom, count in inserted.items():
        if count > 0:
            pool[denom] += count
    return pool


def hole_make_change(amount: int, inventory: Counter) -> Optional[List[int]]:
    """Return the fewest coins from `inventory` summing to `amount`, sorted
    descending, or None if no exact combination exists."""
    if amount == 0:
        return []
    denoms = sorted((d for d, n in inventory.items() if n > 0 and d > 0),
                    reverse=True)
    best: Optional[List[int]] = None

    def search(i: int, remaining: int, chosen: List[int]) -> None:
        nonlocal best
        if remaining == 0:
            if best is None or len(chosen) < len(best):
                best = list(chosen)
            return
        if i == len(denoms):
            return
        d = denoms[i]
        max_k = min(inventory[d], remaining // d)
        for k in range(max_k, -1, -1):
            chosen.extend([d] * k)
            search(i + 1, remaining - k * d, chosen)
            del chosen[len(chosen) - k:]

    search(0, amount, [])
    return best


def hole_commit_sale(stock: Counter, inserted: Counter, change: List[int]) -> Counter:
    """Machine stock after a sale: add the inserted coins, remove the change."""
    result = Counter(stock)
    result.update(inserted)
    result.subtract(Counter(change))
    return Counter({d: c for d, c in result.items() if c > 0})
