from typing import Dict, Hashable, List, Optional, Set

Node = Hashable
Adjacency = Dict[Node, Set[Node]]
Assignment = Dict[Node, int]
PickFn = Callable[[List[Node], Assignment, Adjacency, int], Node]


def hole_precoloring_consistent(adj: Adjacency, fixed: Assignment, k: int) -> bool:
    for c in fixed.values():
        if not isinstance(c, int) or isinstance(c, bool) or not (0 <= c < k):
            return False
    for u, cu in fixed.items():
        for v in adj.get(u, ()):
            if v in fixed and fixed[v] == cu:
                return False  # includes self-loops on precolored nodes
    return True


def hole_pick_next_node(free: List[Node], assignment: Assignment, adj: Adjacency, k: int) -> Node:
    # DSatur-style: most distinct neighbor colors first, then most uncolored neighbors.
    best = None
    best_key = None
    for n in free:
        sat = len({assignment[v] for v in adj.get(n, ()) if v in assignment})
        deg = sum(1 for v in adj.get(n, ()) if v not in assignment)
        key = (sat, deg)
        if best_key is None or key > best_key:
            best, best_key = n, key
    return best


def _hole_backtrack(adj: Adjacency, cur: Assignment, remaining: List[Node], k: int, pick: PickFn) -> Optional[Assignment]:
    if not remaining:
        return cur
    n = pick(remaining, cur, adj, k)
    used = {cur[v] for v in adj.get(n, ()) if v in cur}
    rest = [x for x in remaining if x != n]
    for c in range(k):
        if c in used:
            continue
        cur[n] = c
        res = _hole_backtrack(adj, cur, rest, k, pick)
        if res is not None:
            return res
        del cur[n]
    return None


def hole_solve(adj: Adjacency, assignment: Assignment, free: List[Node], k: int, pick: PickFn) -> Optional[Assignment]:
    # A free node adjacent to itself can never be properly colored.
    for n in free:
        if n in adj.get(n, ()):
            return None
    cur: Assignment = dict(assignment)
    res = _hole_backtrack(adj, cur, list(free), k, pick)
    if res is None:
