def hole_is_valid_interval(start: Number, end: Number) -> bool:
    """Return True if [start, end) may be booked or cancelled, False otherwise."""
    return bool(start < end)


def hole_overlaps(a_start: Number, a_end: Number, b_start: Number, b_end: Number) -> bool:
    """Return True iff [a_start, a_end) and [b_start, b_end) share at least one point."""
    return bool(a_start < b_end and b_start < a_end)


def hole_gaps_in_window(lo: Number, hi: Number, busy: List[Tuple[Number, Number]]) -> List[Tuple[Number, Number]]:
    """Return the maximal free sub-intervals of [lo, hi) as a sorted list of (start, end)."""
    if lo >= hi:
        return []
    gaps: List[Tuple[Number, Number]] = []
    cur = lo
    for s, e in busy:
        cs = max(s, lo)
        ce = min(e, hi)
        if cs >= ce:
            continue
        if cs > cur:
            gaps.append((cur, cs))
        if ce > cur:
            cur = ce
    if cur < hi:
        gaps.append((cur, hi))
    return gaps


def hole_invalid_booking_result(start: Number, end: Number) -> bool:
    """Raise ValueError for an invalid interval (start >= end)."""
    raise ValueError(f"invalid interval [{start}, {end}): start must be less than end")
