"""Greedy word-wrapping with paragraph preservation."""
from typing import List


def hole_split_paragraphs(text: str) -> List[str]:
    """Split raw text into paragraphs separated by blank lines."""
    paragraphs: List[str] = []
    current: List[str] = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped:
            current.append(stripped)
        elif current:
            paragraphs.append('\n'.join(current))
            current = []
    if current:
        paragraphs.append('\n'.join(current))
    return paragraphs


def hole_fill_paragraph(paragraph: str, width: int) -> List[str]:
    """Greedily wrap a single paragraph to at most `width` characters per line."""
    # Break over-long words into width-sized pieces; each piece is a word.
    words: List[str] = []
    for word in paragraph.split():
        for i in range(0, len(word), width):
            words.append(word[i:i + width])

    lines: List[str] = []
    current = ''
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
