    rest: Set[Node] = set(uncolored)
    rest.discard(v)
    forbidden = {coloring[w] for w in adjacency[v] if w in coloring}
    for c in range(k):
        if c in forbidden:
            continue
        coloring[v] = c
        if hole_backtrack(rest, adjacency, coloring, k):
            return True
        del coloring[v]
    return False
