    return result


def hole_choose_next_node(uncolored: Set[Hashable], coloring: Dict[Hashable, int], adjacency: Dict[Hashable, Set[Hashable]], k: int) -> Hashable:
    best = None
    best_key = None
    for node in uncolored:
        legal = len(hole_candidate_colors(node, coloring, adjacency, k))
        key = (legal, -len(adjacency[node]))
        if best_key is None or key < best_key:
            best = node
            best_key = key
    return best


def hole_candidate_colors(node: Hashable, coloring: Dict[Hashable, int], adjacency: Dict[Hashable, Set[Hashable]], k: int) -> List[int]:
    taken = {coloring[nb] for nb in adjacency[node] if nb in coloring}
    return [c for c in range(k) if c not in taken]
