from typing import Dict, Hashable, List, Set, Tuple

Node = Hashable

def hole_admit_unknown_endpoint(node: Node, edge: Tuple[Node, Node], known: Set[Node]) -> bool:
    # Edge endpoints missing from `nodes` are treated as additional graph nodes.
    return True

def hole_pick_next_node(uncolored: Set[Node], adj: Dict[Node, Set[Node]], assignment: Dict[Node, int], k: int) -> Node:
    # Most-constrained-first: fewest colors still available, then most uncolored
    # neighbours, then repr() as a deterministic tie-breaker.
    def available_count(n: Node) -> int:
        used = {assignment[m] for m in adj[n] if m in assignment}
        return k - len(used)

    def uncolored_degree(n: Node) -> int:
        return sum(1 for m in adj[n] if m in uncolored)

    return min(uncolored, key=lambda n: (available_count(n), -uncolored_degree(n), repr(n)))

def hole_color_order(node: Node, adj: Dict[Node, Set[Node]], assignment: Dict[Node, int], k: int) -> List[int]:
    # Least-constraining-value ordering: prefer colors that remove the fewest
    # options from uncolored neighbours (i.e. colors they already cannot use).
    uncolored_nbrs = [m for m in adj[node] if m not in assignment]
    used_by_nbr = {
        m: {assignment[x] for x in adj[m] if x in assignment}
        for m in uncolored_nbrs
    }

    def cost(c: int) -> int:
        return sum(1 for m in uncolored_nbrs if c not in used_by_nbr[m])

    return sorted(range(k), key=lambda c: (cost(c), c))
