def hole_all_packages(graph: dict[str, list[str]]) -> set[str]:
    names = set(graph)
    for requires in graph.values():
        names.update(requires)
    return names


def hole_pick_next(ready: set[str]) -> str:
    return min(ready)


def hole_find_cycle(stuck: dict[str, list[str]]) -> list[str]:
    start = min(stuck)
    path: list[str] = []
    position: dict[str, int] = {}
    node = start
    while node not in position:
        position[node] = len(path)
        path.append(node)
        node = stuck[node][0]
    return path[position[node]:] + [node]
```

