import re


_NUMERIC_ID_RE = re.compile(r'[0-9]+')


def hole_compare_identifiers(a: str, b: str) -> int:
    a_numeric = _NUMERIC_ID_RE.fullmatch(a) is not None
    b_numeric = _NUMERIC_ID_RE.fullmatch(b) is not None

    if a_numeric and b_numeric:
        na, nb = int(a), int(b)
        return (na > nb) - (na < nb)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def hole_compare_prerelease(a: tuple, b: tuple) -> int:
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for x, y in zip(a, b):
        result = hole_compare_identifiers(x, y)
        if result != 0:
            return result

    return (len(a) > len(b)) - (len(a) < len(b))
```

